/*!************************************************
* Name		: Forum with Blogspot
* Version	: v0.1
* Website	: https://www.facebook.com/olalavui
**************************************************/
:root {
--lime: $(keycolor);
--dark: #161616;
--mediumdark: #262626;
--dark34: #343434;
--darker: #4f4f4f;
--white: #fff;
--surface: #1f1f1f;
--surface2: #2b2b2b;
--border: #3b3b3b;
--muted: #8f8f8f;
--light: #bdbdbd;
--mediumlight: #CCCCCC;
--radius: 8px;
--shadow: 0 10px 28px rgba(0,0,0,.2)
}
html {
    font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, 'Helvetica Neue', sans-serif;
    font-weight: 400;
    word-wrap: break-word;
}
.dark-mode {
    background-color: black;
    color: white;
}
.modeSwitch{position:relative;display:inline-block;width:30px;height:17px}
.modeSwitch input{opacity:0;width:0;height:0}
.toggleSwitch{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background-color:#ccc;transition:.4s;border-radius:17px}
.toggleSwitch:before{position:absolute;content:"";height:13px;width:13px;left:2px;bottom:2px;background-color:#fff;transition:.4s;border-radius:50%}
.dark-mode input+.toggleSwitch{background-color:#666}
input:focus+.toggleSwitch{box-shadow:0 0 1px #2196f3}
.dark-mode input+.toggleSwitch:before{transform:translateX(13px)}

*,*::before,*::after{box-sizing:border-box}
body{margin:0;background:var(--dark);color:var(--light);font-size:16px;line-height:1.65;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto}
button,input,textarea,select{font:inherit}
.post-body,.post-body p{line-height:1.75}
.post-body h2,.post-body h3{color:var(--white);line-height:1.3;margin:1.6em 0 .7em}
.post-body blockquote{margin:1rem 0;padding:12px 16px;border-left:4px solid var(--lime);background:var(--surface2);border-radius:var(--radius)}
.post-body table{width:100%;border-collapse:collapse;overflow:auto;display:block}
.post-body th,.post-body td{border:1px solid var(--border);padding:8px 10px}
.post-body code{background:#111;padding:.15rem .35rem;border-radius:4px}
.post-body pre{background:#111;padding:14px;border-radius:var(--radius);overflow:auto}
.header-widget{min-height:92px;align-items:center;justify-content:center;padding:18px;background:linear-gradient(135deg,var(--lime),#34d399)}
.header-widget h1{line-height:1.2}
.widget-content a,.post-title a{overflow-wrap:anywhere}
.tabs,.widget-content ul{gap:10px;flex-wrap:wrap}
.label-size a,.post-labels a{display:inline-block;margin:3px 4px 3px 0;padding:3px 8px;border:1px solid var(--border);border-radius:999px;background:var(--surface)}
.related.style-2{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;list-style:none;padding:0;margin:0}
.related .item-related{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;height:100%}
.related .item-thumbnail img{width:100%;aspect-ratio:16/9;object-fit:cover;display:block}
.related .item-title{padding:8px 10px;font-weight:600}
.notice-card{background:var(--surface2);border:1px solid var(--border);border-left:4px solid var(--lime);border-radius:var(--radius);padding:12px 14px}
.cta-box{margin:20px 0;padding:16px;border-radius:var(--radius);background:linear-gradient(135deg,rgba(108,108,254,.18),rgba(52,211,153,.12));border:1px solid var(--border)}
.cta-box .button{display:inline-block;margin-top:8px;padding:8px 12px;border-radius:6px;background:var(--lime);color:#fff;font-weight:700}
.nav-main{display:flex;align-items:center;gap:14px;min-width:0;overflow:visible}
.nav-main>li{min-width:0;white-space:nowrap}
.nav-main .mra{margin-left:auto}
.nav-meta{display:flex;align-items:center;justify-content:flex-end;gap:10px;min-width:0;overflow:hidden;color:var(--lime)}
.nav-social{display:flex;align-items:center;justify-content:flex-end;gap:10px;min-width:0;max-width:100%;overflow:hidden;white-space:nowrap}
.nav-social a{display:inline-flex;align-items:center;min-width:0;max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.breadcrumb-nav{margin:0 0 10px;padding:7px 10px;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);font-size:.82rem;color:var(--muted);overflow:hidden}
.breadcrumb-nav ol{display:flex;gap:6px;align-items:center;flex-wrap:nowrap;min-width:0;margin:0;padding:0;list-style:none}
.breadcrumb-nav li{display:inline-flex;align-items:center;min-width:0;white-space:nowrap}
.breadcrumb-nav li:not(:last-child){flex:0 0 auto}
.breadcrumb-nav li:not(:last-child)::after{content:"›";margin-left:6px;color:var(--darker)}
.breadcrumb-nav li:last-child{flex:1 1 auto;overflow:hidden;text-overflow:ellipsis}
.breadcrumb-nav li:last-child span{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.breadcrumb-nav a{color:var(--light)}
.toc-box{display:none;margin:14px 0 18px;padding:12px 14px;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface)}
.toc-box.active{display:block}
.toc-title{margin:0 0 8px;color:var(--white);font-weight:700}
.toc-list{margin:0;padding-left:18px}
.toc-list li{margin:4px 0}
.toc-list .toc-h3{margin-left:14px;font-size:.92em}
.post-body h2[id],.post-body h3[id]{scroll-margin-top:76px}
.post-note{margin:14px 0;padding:10px 12px;border:1px solid var(--border);border-left:4px solid #34d399;border-radius:var(--radius);background:rgba(52,211,153,.08)}
.home-category-sections{display:grid;gap:16px}
.home-category-block{background:var(--mediumdark);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden}
.home-category-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:7px 10px;border-bottom:2px solid var(--lime);background:var(--dark34)}
.home-category-title{margin:0;color:var(--white);font-size:1rem;font-weight:700}
.home-category-more{flex:0 0 auto;font-size:.82rem;color:var(--lime)}
.home-category-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;padding:12px}
.home-category-card{display:grid;grid-template-columns:72px minmax(0,1fr);gap:10px;min-width:0;color:var(--light)}
.home-category-thumb{width:72px;aspect-ratio:1/1;border-radius:6px;background:var(--dark34);object-fit:cover}
.home-category-card-title{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;color:#eaf5df;font-weight:700;line-height:1.35}
.home-category-card-snippet{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin-top:4px;color:var(--mediumlight);font-size:.86rem;line-height:1.45}
.home-category-empty{padding:12px;color:var(--muted);font-size:.9rem}
.home-category-loading{padding:12px;color:var(--muted);font-size:.9rem}
.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 10px;border-bottom:2px solid var(--lime);background:var(--dark34)}
.section-title{margin:0;color:var(--white);font-size:1rem;font-weight:700}
.section-note{color:var(--muted);font-size:.82rem;white-space:nowrap}
.featured-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;padding:12px}
.featured-card{display:flex;flex-direction:column;min-width:0;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);overflow:hidden;transition:transform .18s ease,border-color .18s ease}
.featured-card:hover{transform:translateY(-2px);border-color:var(--lime)}
.featured-thumb-link{display:block;background:var(--dark34)}
.featured-thumb{width:100%;aspect-ratio:16/9;object-fit:cover;display:block;background:var(--dark34)}
.featured-body{display:flex;flex-direction:column;gap:7px;padding:10px;min-width:0}
.featured-title{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin:0;color:#eaf5df;font-size:1rem;font-weight:700;line-height:1.4}
.featured-title a{color:inherit}
.featured-snippet{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;margin:0;color:var(--mediumlight);font-size:.9rem;line-height:1.55}
.post-meta-line{display:flex;align-items:center;flex-wrap:wrap;gap:8px;color:var(--muted);font-size:.78rem}
.post-meta-pill{display:inline-flex;align-items:center;gap:4px;min-width:0}
.latest-list{display:grid;gap:0;background:var(--mediumdark)}
.latest-card{display:grid;grid-template-columns:96px minmax(0,1fr);gap:12px;padding:12px;border-bottom:1px solid var(--border);min-width:0}
.latest-card:last-child{border-bottom:0}
.latest-card:hover{background:rgba(255,255,255,.025)}
.latest-thumb-link{display:block;align-self:start;background:var(--dark34);border-radius:6px;overflow:hidden}
.latest-thumb{width:96px;aspect-ratio:1/1;object-fit:cover;display:block;background:var(--dark34)}
.latest-body{min-width:0}
.latest-title{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin:0 0 5px;color:#eaf5df;font-size:1rem;font-weight:700;line-height:1.45}
.latest-title a{color:inherit}
.latest-snippet{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin:0 0 8px;color:var(--mediumlight);font-size:.9rem;line-height:1.55}
.badge-new{display:inline-flex;align-items:center;margin-right:5px;padding:1px 5px;border-radius:3px;background:#c000d8;color:#fff;font-size:.68rem;font-weight:700;vertical-align:middle}


@media (max-width:650px){body{font-size:15px}.header-widget{min-height:72px;padding:12px}.fs-30{font-size:1.35rem}.gtc{grid-template-columns:1fr 64px auto}.mod-mobile{display:none}.post-body{font-size:1rem}.related.style-2{grid-template-columns:1fr}.breadcrumb-nav{font-size:.78rem}.toc-box{padding:10px 12px}.nav-main{gap:10px;flex-wrap:wrap}.nav-main .mra{margin-left:0}.nav-meta{display:none}.home-category-grid{grid-template-columns:1fr}.home-category-card{grid-template-columns:64px minmax(0,1fr)}.home-category-thumb{width:64px}.featured-grid{grid-template-columns:1fr;padding:10px}.latest-card{grid-template-columns:72px minmax(0,1fr);padding:10px}.latest-thumb{width:72px}.section-note{display:none}}

