#ContactForm1 {
    padding: 10px;
    background-color: #262626;
    border-radius: 7px;
    margin-bottom: 16px;
}

.auth {
    color: crimson;
}


.dropdown {
    padding: 5px;
    position: absolute;
    background-color: #262626;
    min-width: 125px;
    top: 32px;
    border: 1px solid #323232;
    user-select: none;
    pointer-events: none;
    opacity: 0;
	list-style: none;
	border-radius: 5px;
}
.dropdown::before {
    width: 0;
    height: 0;
    content: "";
    z-index: 2;
    transform: scale(1.01);
    border-bottom: .6rem solid currentColor;
    border-left: .4rem solid transparent;
    border-right: .4rem solid transparent;
    bottom: 100%;
    color: #464343;
    left: 30%;
    position: absolute;
}
.sidenav:hover .dropdown {
    animation: dropdown .25s;
    opacity: 1;
    pointer-events: auto;
    -webkit-user-select: auto;
    -ms-user-select: auto;
    user-select: auto;
}
.dropdown a {
    padding: 3px 5px;
    display: block;
    border-bottom: 1px solid #323232;
    font-size: .9rem;
}
.dropdown li:last-child a {
    border-bottom: none;
}
.sidenav {
    margin-right: 20px;
}

.arrow::after {
    position: absolute;
    content: "";
    top: 11px;
    right: -12px;
    border-width: 5px;
    border-style: solid;
    border-left-color: transparent;
    border-right-color: transparent;
    border-top-color: gray;
    border-bottom-color: transparent;
}
@keyframes dropdown {
 0% {
  opacity:0;
  transform:translateY(-5px)
 }
 60% {
  opacity:1
 }
 to {
  transform:none
 }
}
.auth .mod::after {
    content: 'Moderator';
    background-color: crimson;
    font-size: .8rem;
    padding: 1px 6px;
    border-radius: 3px;
    color: white;
}
.badge[data*="05392949523370725401"] .user::after,.badge[data*="03154847453392863357"] .user::after,.badge[data*="08331039781819404352"] .user::after {
    content: 'Senpai';
    background-color: brown;
    font-size: .8rem;
    padding: 1px 6px;
    border-radius: 3px;
    color: white;
}

.badge[data*="02480525259652322034"] .user::after {
