@keyframes rainbow {0% {background:rgba(0,105,255,.71)}10% {background:rgba(100,0,255,.71)}20% {background:rgba(255,0,139,.71)}30% {background:rgba(255,0,0,.71)}40% {background:rgba(255,96,0,.71)}50% {background:rgba(202,255,0,.71)}60% {background:rgba(0,255,139,.71)}70% {background:rgba(202,255,0,.71)}80% {background:rgba(255,96,0,.71)}85% {background:rgba(255,0,0,.71)}90% {background:rgba(255,0,139,.71)}95% {background:rgba(100,0,255,.71)}to {background:rgba(0,105,255,.71)}}

.downloadbtn{text-align:center; margin-top: 20px; margin-bottom: 20px;border: dotted;padding-top: 15px;padding-bottom: 15px;background: whitesmoke;}
.downloadbtn a.button:hover {background-color: #ff3d00!important;}

/* =========================================================
   HVA Clean Home Cards v2.0.1.5
   Muc tieu:
   - Bo metadata gay roi o trang chu: 0 binh luan, gio cap nhat, tac gia
   - Doi sang badge label gon hon
   - Them option bat/tat qua widget "Theme Options" trong Blogger Layout
   ========================================================= */
html.hva-hide-home-meta body.fv .featured-card .post-meta-line,
html.hva-hide-home-meta body.fv .latest-card .post-meta-line,
body.fv .featured-card .post-meta-line.is-legacy-meta,
body.fv .latest-card .post-meta-line.is-legacy-meta {
  display: none !important;
}

html.hva-hide-label-badges .post-card-badges {
  display: none !important;
}

html.hva-compact-home-list body.fv .featured-body {
  gap: 6px;
  padding: 11px 12px 12px;
}

html.hva-compact-home-list body.fv .featured-snippet,
html.hva-compact-home-list body.fv .latest-snippet {
  margin-bottom: 0;
}

html.hva-compact-home-list body.fv .featured-snippet {
  -webkit-line-clamp: 2;
}

html.hva-compact-home-list body.fv .latest-snippet {
  -webkit-line-clamp: 2;
}

html.hva-compact-home-list body.fv .latest-card {
  padding-top: 10px;
  padding-bottom: 10px;
}

html.hva-home-hover body.fv .featured-card {
  border-radius: 10px;
}

html.hva-home-hover body.fv .featured-card:hover {
  box-shadow: var(--shadow);
}

html.hva-home-hover body.fv .featured-thumb,
html.hva-home-hover body.fv .latest-thumb {
  transition: transform .22s ease;
}

html.hva-home-hover body.fv .featured-card:hover .featured-thumb,
html.hva-home-hover body.fv .latest-card:hover .latest-thumb {
  transform: scale(1.035);
}

.post-card-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin: 0 0 6px;
}

.post-card-badge {
  display: inline-flex;
  align-items: center;
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 1px 7px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(255,255,255,.035);
  color: var(--mediumlight);
  font-size: .72rem;
  line-height: 1.7;
}

.post-card-badge:hover {
  border-color: var(--lime);
  color: var(--white);
  text-decoration: none;
}

.badge-new {
  border-radius: 999px;
  padding: 2px 7px;
  text-transform: uppercase;
  letter-spacing: .02em;
}


/* =========================================================
   HVA UI Polish & Discovery v2.0.1.6
   Muc tieu:
   - Lam gon label cloud / chuyen muc
   - Them search box cho homepage
   - Dong nhat category sections
   - Toi uu Latest list, pagination, footer
   - Dua nhieu tuy chon vao widget "Theme Options"
   ========================================================= */

/* Search box */
.hva-search-box {
  margin: 0;
  padding: 12px;
  border-radius: 10px;
  background: var(--mediumdark);
  border: 1px solid var(--border);
  overflow: hidden;
}

.hva-search-box form {
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  gap: 8px;
}

.hva-search-box input {
  width: 100%;
  min-height: 42px;
  padding: 0 13px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--dark);
  color: var(--white);
  outline: none;
}

.hva-search-box input:focus {
  border-color: var(--lime);
  box-shadow: 0 0 0 3px rgba(108,108,254,.12);
}

.hva-search-box button {
  min-height: 42px;
  padding: 0 16px;
  border: 0;
  border-radius: 8px;
  background: var(--lime);
  color: #fff;
  font-weight: 700;
  cursor: pointer;
}

.hva-search-box button:hover {
  filter: brightness(1.06);
}

html.hva-hide-home-search body.fv .hva-search-box,
html.hva-hide-home-search body.fv #HTML98 {
  display: none !important;
}

/* Label cloud / Categories */
html.hva-compact-label-cloud .Label .widget-content,
html.hva-compact-label-cloud .cloud-label-widget-content {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 4px 0 10px;
}

html.hva-compact-label-cloud .label-size,
html.hva-compact-label-cloud .label-size a {
  margin: 0 !important;
}

html.hva-compact-label-cloud .label-size a {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 4px 11px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(255,255,255,.035);
  color: var(--mediumlight);
  font-size: .84rem;
  line-height: 1.35;
}

html.hva-compact-label-cloud .label-size a:hover {
  border-color: var(--lime);
  background: rgba(108,108,254,.12);
  color: var(--white);
  text-decoration: none;
}

html.hva-compact-label-cloud .cloud-label-widget-content .hva-label-extra {
  display: none;
}

html.hva-compact-label-cloud .cloud-label-widget-content.is-expanded .hva-label-extra {
  display: inline-flex;
}

.hva-label-toggle {
  min-height: 30px;
  padding: 4px 11px;
  border: 1px dashed var(--darker);
  border-radius: 999px;
  background: transparent;
  color: var(--lime);
  cursor: pointer;
  font-size: .84rem;
}

.hva-label-toggle:hover {
  border-color: var(--lime);
  color: var(--white);
}

/* Home category sections */
html.hva-category-compact .home-category-block,
html.hva-category-detailed .home-category-block {
  border-radius: 10px;
  overflow: hidden;
  background: var(--mediumdark);
  border: 1px solid var(--border);
}

html.hva-category-compact .home-category-head,
html.hva-category-detailed .home-category-head {
  min-height: 43px;
  padding: 9px 11px;
}

html.hva-category-compact .home-category-title,
html.hva-category-detailed .home-category-title {
  font-size: .98rem;
  letter-spacing: .01em;
}

html.hva-category-compact .home-category-more,
html.hva-category-detailed .home-category-more {
  font-size: .8rem;
  opacity: .9;
}

html.hva-category-compact .home-category-grid,
html.hva-category-detailed .home-category-grid {
  grid-template-columns: repeat(auto-fit,minmax(240px,1fr));
  gap: 12px;
  padding: 12px;
}

html.hva-category-compact .home-category-card,
html.hva-category-detailed .home-category-card {
  grid-template-columns: 80px minmax(0,1fr);
  gap: 11px;
  padding: 6px;
  border-radius: 8px;
  transition: background .18s ease, transform .18s ease;
}

html.hva-category-compact .home-category-card:hover,
html.hva-category-detailed .home-category-card:hover {
  background: rgba(255,255,255,.035);
  transform: translateY(-1px);
}

html.hva-category-compact .home-category-thumb,
html.hva-category-detailed .home-category-thumb {
  width: 80px;
  border-radius: 8px;
}

html.hva-category-compact .home-category-card-title,
html.hva-category-detailed .home-category-card-title {
  -webkit-line-clamp: 2;
  font-size: .96rem;
}

html.hva-category-compact .home-category-card-snippet {
  -webkit-line-clamp: 2;
  font-size: .84rem;
  opacity: .9;
}

html.hva-category-detailed .home-category-card {
  grid-template-columns: 96px minmax(0,1fr);
}

html.hva-category-detailed .home-category-thumb {
  width: 96px;
}

html.hva-category-detailed .home-category-card-snippet {
  -webkit-line-clamp: 3;
}

/* Latest list polish */
html.hva-compact-home-list body.fv .latest-card {
  grid-template-columns: 88px minmax(0,1fr);
  gap: 13px;
  padding: 13px 14px;
}

html.hva-compact-home-list body.fv .latest-thumb {
  width: 88px;
  border-radius: 8px;
}

html.hva-compact-home-list body.fv .latest-title {
  margin-bottom: 5px;
  font-size: 1rem;
  line-height: 1.38;
  -webkit-line-clamp: 2;
}

html.hva-compact-home-list body.fv .latest-snippet {
  margin-top: 6px;
  margin-bottom: 0;
  font-size: .88rem;
  line-height: 1.5;
  -webkit-line-clamp: 2;
}

html.hva-compact-home-list body.fv .latest-card:hover {
  background: rgba(255,255,255,.032);
}

.post-card-cta {
  display: inline-flex;
  align-items: center;
  margin-top: 6px;
  color: var(--lime);
  font-size: .82rem;
  font-weight: 700;
}

.post-card-cta:hover {
  color: var(--white);
  text-decoration: none;
}

html.hva-hide-latest-cta .post-card-cta {
  display: none !important;
}

/* Colored label badges */
html.hva-colored-label-badges .post-card-badge[href*="Google-Ads"],
html.hva-colored-label-badges .post-card-badge[href*="Google-Adwords"],
html.hva-colored-label-badges .post-card-badge[href*="Google%20Ads"],
html.hva-colored-label-badges .post-card-badge[href*="Google%20Adwords"] {
  border-color: rgba(66,133,244,.55);
  color: #bcd7ff;
}

html.hva-colored-label-badges .post-card-badge[href*="Google-Analytics"],
html.hva-colored-label-badges .post-card-badge[href*="Google%20Analytics"] {
  border-color: rgba(251,188,5,.55);
  color: #ffe49a;
}

html.hva-colored-label-badges .post-card-badge[href*="Google-My-Business"],
html.hva-colored-label-badges .post-card-badge[href*="Google%20My%20Business"] {
  border-color: rgba(52,168,83,.55);
  color: #bdf5cf;
}

html.hva-colored-label-badges .post-card-badge[href*="Search-Advertising"],
html.hva-colored-label-badges .post-card-badge[href*="Search%20Advertising"] {
  border-color: rgba(108,108,254,.7);
  color: #d2d2ff;
}

html.hva-colored-label-badges .post-card-badge[href*="Video-Advertising"],
html.hva-colored-label-badges .post-card-badge[href*="Video%20Advertising"] {
  border-color: rgba(255,99,99,.6);
  color: #ffc4c4;
}

html.hva-colored-label-badges .post-card-badge[href*="Google-App"],
html.hva-colored-label-badges .post-card-badge[href*="Google%20App"] {
  border-color: rgba(52,211,153,.55);
  color: #bff6df;
}

/* Pagination */
html.hva-modern-pagination .showpageOf,
html.hva-modern-pagination .displaypageNum,
html.hva-modern-pagination .pagecurrent,
html.hva-modern-pagination .firstpage {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 2px 9px;
  margin: 0 3px;
  border-radius: 7px;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--mediumlight);
  font-size: .82rem;
}

html.hva-modern-pagination .pagecurrent {
  background: var(--lime);
  border-color: var(--lime);
  color: #fff;
  font-weight: 700;
}

html.hva-modern-pagination .displaypageNum:hover,
html.hva-modern-pagination .firstpage:hover {
  border-color: var(--lime);
}

html.hva-modern-pagination .showpageOf {
  color: var(--muted);
}

/* Optional sections */
html.hva-hide-recent-comments body.fv #HTML4,
html.hva-hide-recent-comments body.fv #recent-comments,
html.hva-hide-recent-comments body.fv .recent-comments {
  display: none !important;
}

html.hva-hide-useful-links body.fv #HTML1 {
  display: none !important;
}

html.hva-hide-theme-version .theme-version {
  display: none !important;
}

html.hva-hide-footer-powered .footer-powered {
  display: none !important;
}

html.hva-hide-footer-date #time {
  display: none !important;
}

.footer-copyright,
.theme-version,
.footer-powered {
  margin: 2px 0;
}

@media (max-width:650px) {
  .hva-search-box {
    padding: 10px;
  }
  .hva-search-box form {
    grid-template-columns: 1fr;
  }
  html.hva-compact-home-list body.fv .latest-card {
    grid-template-columns: 72px minmax(0,1fr);
    gap: 10px;
    padding: 11px 10px;
  }
  html.hva-compact-home-list body.fv .latest-thumb {
    width: 72px;
  }
  html.hva-category-compact .home-category-grid,
  html.hva-category-detailed .home-category-grid {
    grid-template-columns: 1fr;
  }
  html.hva-category-compact .home-category-card,
  html.hva-category-detailed .home-category-card {
    grid-template-columns: 64px minmax(0,1fr);
  }
  html.hva-category-compact .home-category-thumb,
  html.hva-category-detailed .home-category-thumb {
    width: 64px;
  }
}



/* =========================================================
   HVA Display Mode & Layout Options v2.0.1.7
   Muc tieu:
   - Them che do Sang / Toi
   - Them che do Fixed screen / Full screen
   - Co nut chuyen nhanh ngoai giao dien va luu lua chon theo trinh duyet
   ========================================================= */
:root {
  --hva-fixed-width: 1200px;
  --hva-screen-gutter: 16px;
}

/* Layout width modes */
html.hva-layout-fixed .max-w {
  width: calc(100% - (var(--hva-screen-gutter) * 2));
  max-width: var(--hva-fixed-width) !important;
}

html.hva-layout-full .max-w {
  width: calc(100% - (var(--hva-screen-gutter) * 2));
  max-width: none !important;
}

html.hva-layout-full .featured-grid {
  grid-template-columns: repeat(auto-fit,minmax(260px,1fr));
}

html.hva-layout-full .home-category-grid {
  grid-template-columns: repeat(auto-fit,minmax(280px,1fr));
}

html.hva-layout-full .latest-card {
  grid-template-columns: 96px minmax(0,1fr);
}

html.hva-layout-full .latest-thumb {
  width: 96px;
}

/* Light theme palette - softer, less harsh */
html.hva-theme-light {
  --lime: #5b5ce6;
  --dark: #edf1f7;
  --mediumdark: #f8fafc;
  --dark34: #f1f4f9;
  --darker: #94a3b8;
  --white: #172033;
  --surface: #f8fafc;
  --surface2: #f1f5f9;
  --border: #d8e0ec;
  --muted: #64748b;
  --light: #475569;
  --mediumlight: #334155;
  --shadow: 0 10px 26px rgba(15,23,42,.10);
}

html.hva-theme-light body {
  background: linear-gradient(180deg,#eef2f7 0%,#e9eef5 100%);
  color: var(--light);
}

html.hva-theme-light a {
  color: #4f46e5;
}

html.hva-theme-light .featured-title,
html.hva-theme-light .latest-title,
html.hva-theme-light .home-category-card-title,
html.hva-theme-light .section-title,
html.hva-theme-light .home-category-title {
  color: var(--white);
  text-shadow: none;
}

html.hva-theme-light .featured-snippet,
html.hva-theme-light .latest-snippet,
html.hva-theme-light .home-category-card-snippet,
html.hva-theme-light .post-body,
html.hva-theme-light .comment-body {
  color: var(--light);
}

html.hva-theme-light .g161 {
  background: transparent;
}

html.hva-theme-light .g262,
html.hva-theme-light .home-category-block,
html.hva-theme-light .featured-card,
html.hva-theme-light .latest-list,
html.hva-theme-light #ContactForm1,
html.hva-theme-light .hva-search-box {
  background: var(--mediumdark);
}

html.hva-theme-light .g343,
html.hva-theme-light .section-head,
html.hva-theme-light .home-category-head {
  background: var(--dark34);
}

html.hva-theme-light .featured-card,
html.hva-theme-light .latest-card,
html.hva-theme-light .home-category-block,
html.hva-theme-light .hva-search-box,
html.hva-theme-light #ContactForm1,
html.hva-theme-light .breadcrumb-nav,
html.hva-theme-light .toc-box,
html.hva-theme-light .notice-card {
  border-color: var(--border);
  box-shadow: 0 1px 2px rgba(15,23,42,.035);
}

html.hva-theme-light .latest-card,
html.hva-theme-light .bb {
  border-bottom-color: var(--border);
}

html.hva-theme-light .latest-card:hover,
html.hva-theme-light .home-category-card:hover,
html.hva-theme-light .featured-card:hover {
  background: #f3f6fb;
}

html.hva-theme-light .post-card-badge,
html.hva-theme-light .label-size a,
html.hva-theme-light .hva-label-toggle,
html.hva-theme-light .displaypageNum,
html.hva-theme-light .showpageOf,
html.hva-theme-light .firstpage {
  background: #f3f6fb;
  border-color: #d5deeb;
  color: #475569;
}

html.hva-theme-light .post-card-badge:hover,
html.hva-theme-light .label-size a:hover,
html.hva-theme-light .hva-label-toggle:hover {
  background: #eef2ff;
  border-color: rgba(91,92,230,.45);
  color: #3730a3;
}

html.hva-theme-light .hva-search-box input {
  background: #ffffff;
  border-color: #d5deeb;
  color: var(--white);
}

html.hva-theme-light .hva-search-box input::placeholder {
  color: #8b95a7;
}

html.hva-theme-light .hva-search-box button,
html.hva-theme-light .pagecurrent,
html.hva-theme-light .badge-new {
  background: #5b5ce6;
  color: #fff;
}

html.hva-theme-light .header-widget {
  background: linear-gradient(135deg,#4f46e5,#0891b2);
}

html.hva-theme-light .header-widget .cfff,
html.hva-theme-light .header-widget h1,
html.hva-theme-light .header-widget a,
html.hva-theme-light .header-widget p {
  color: #fff !important;
}

html.hva-theme-light .dropdown {
  background: #ffffff;
  border-color: var(--border);
  box-shadow: var(--shadow);
}

html.hva-theme-light .dropdown::before {
  color: #ffffff;
}

html.hva-theme-light .ce5b {
  color: #f9d7df;
}

html.hva-theme-light .g4d0 {
  background-color: #4d000d;
}

html.hva-theme-light .downloadbtn {
  background: #ffffff;
  color: #111827;
  border-color: #d5deeb;
}

html.hva-theme-light.hva-colored-label-badges .post-card-badge[href*="Google-Ads"],
html.hva-theme-light.hva-colored-label-badges .post-card-badge[href*="Google-Adwords"] {
  background: #eef5ff;
  color: #285a9f;
}

html.hva-theme-light.hva-colored-label-badges .post-card-badge[href*="Google-Analytics"] {
  background: #fff7e6;
  color: #8a5b00;
}

html.hva-theme-light.hva-colored-label-badges .post-card-badge[href*="Google-My-Business"] {
  background: #edfdf3;
  color: #187044;
}

html.hva-theme-light.hva-colored-label-badges .post-card-badge[href*="Search-Advertising"] {
  background: #f1f0ff;
  color: #4338ca;
}

html.hva-theme-light.hva-colored-label-badges .post-card-badge[href*="Video-Advertising"] {
  background: #fff1f2;
  color: #9f1239;
}

/* Floating display switch - compact */
.hva-display-switch {
  position: fixed;
  right: 14px;
  bottom: 14px;
  z-index: 9999;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--surface);
  box-shadow: 0 8px 24px rgba(0,0,0,.16);
  backdrop-filter: blur(10px);
}

.hva-display-switch[hidden] {
  display: none !important;
}

.hva-display-switch button {
  min-width: 42px;
  min-height: 32px;
  padding: 0 9px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: transparent;
  color: var(--mediumlight);
  font-size: .76rem;
  font-weight: 800;
  line-height: 1;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

.hva-display-switch button:hover {
  border-color: rgba(108,108,254,.45);
  color: var(--white);
  background: rgba(108,108,254,.08);
}

.hva-display-switch button.is-active,
.hva-display-switch button:active {
  background: var(--lime);
  border-color: var(--lime);
  color: #fff;
}

.hva-display-switch .hva-switch-label {
  display: none;
}

html.hva-switcher-labels .hva-display-switch .hva-switch-label,
.hva-display-switch.is-full .hva-switch-label {
  display: inline;
}

html.hva-switcher-labels .hva-display-switch button,
.hva-display-switch.is-full button {
  min-width: 0;
  padding: 0 10px;
}

html.hva-switcher-bottom-center .hva-display-switch {
  left: 50%;
  right: auto;
  transform: translateX(-50%);
}

html.hva-theme-light .hva-display-switch {
  background: rgba(248,250,252,.94);
  box-shadow: 0 8px 22px rgba(15,23,42,.14);
}

html.hva-theme-light .hva-display-switch button:hover {
  background: #eef2ff;
  color: #3730a3;
}

html.hva-hide-display-switch .hva-display-switch {
  display: none !important;
}

@media (min-width:1440px) {
  :root {
    --hva-screen-gutter: 24px;
  }
}

@media (max-width:650px) {
  :root {
    --hva-screen-gutter: 10px;
  }
  .hva-display-switch {
    left: 50%;
    right: auto;
    bottom: 10px;
    transform: translateX(-50%);
    max-width: calc(100% - 20px);
    overflow-x: auto;
  }
  .hva-display-switch button {
    min-height: 32px;
    padding: 0 9px;
    white-space: nowrap;
  }
  html.hva-layout-full .latest-card,
  html.hva-layout-fixed .latest-card {
    grid-template-columns: 72px minmax(0,1fr);
  }
  html.hva-layout-full .latest-thumb,
  html.hva-layout-fixed .latest-thumb {
    width: 72px;
  }
}


/* =========================================================
   HVA Readable Theme & Post Polish v2.0.1.9
   Muc tieu:
   - Giam roi mat o trang bai viet
   - Toi uu mau sang / toi de chu de doc hon
   - Gioi han do rong dong chu khi dung full screen
   ========================================================= */
:root {
  --hva-post-width: 1180px;
  --hva-reading-width: 860px;
  --hva-text-strong: #f8fafc;
  --hva-text-body: #d7dde8;
  --hva-text-muted: #9aa4b2;
  --hva-card-bg: #202124;
  --hva-card-soft: #26282d;
}

html.hva-theme-dark {
  --dark: #111315;
  --mediumdark: #1b1d20;
  --dark34: #24272b;
  --darker: #666f7d;
  --surface: #1d2024;
  --surface2: #252930;
  --border: #343941;
  --muted: #9aa4b2;
  --light: #d7dde8;
  --mediumlight: #eef2f7;
  --white: #f8fafc;
  --hva-text-strong: #f8fafc;
  --hva-text-body: #d7dde8;
  --hva-text-muted: #9aa4b2;
  --hva-card-bg: #1d2024;
  --hva-card-soft: #252930;
  --shadow: 0 14px 34px rgba(0,0,0,.28);
}

html.hva-theme-light {
  --dark: #f3f6fb;
  --mediumdark: #ffffff;
  --dark34: #f6f8fc;
  --darker: #7c8798;
  --surface: #ffffff;
  --surface2: #f8fafc;
  --border: #dde5f0;
  --muted: #697586;
  --light: #344054;
  --mediumlight: #1f2937;
  --white: #111827;
  --hva-text-strong: #111827;
  --hva-text-body: #344054;
  --hva-text-muted: #697586;
  --hva-card-bg: #ffffff;
  --hva-card-soft: #f8fafc;
  --shadow: 0 10px 28px rgba(15,23,42,.08);
}

html.hva-theme-light body {
  background: #f3f6fb;
  color: var(--hva-text-body);
}

html.hva-theme-dark body {
  background: #111315;
  color: var(--hva-text-body);
}

/* Contain post content even when the global layout is full screen */
html.hva-post-contained body.hva-post-page main.max-w {
  max-width: var(--hva-post-width) !important;
}

body.hva-post-page main.max-w {
  color: var(--hva-text-body);
}

/* Post title and top details */
html.hva-compact-post-header body.hva-post-page h1.fs-1d3 {
  margin: 0 0 10px;
  color: var(--hva-text-strong);
  font-size: clamp(1.35rem, 1.1rem + 1vw, 2rem);
  font-weight: 800;
  line-height: 1.32;
  letter-spacing: -.015em;
}

body.hva-post-page .breadcrumb-nav {
  margin-bottom: 12px;
  padding: 8px 11px;
  border-radius: 10px;
  background: var(--hva-card-soft);
  color: var(--hva-text-muted);
  font-size: .82rem;
}

body.hva-post-page .breadcrumb-nav a {
  color: var(--hva-text-muted);
}

body.hva-post-page .breadcrumb-nav a:hover {
  color: var(--lime);
}

body.hva-post-page .flex.jcsb.mb-7 {
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

body.hva-post-page .flex.jcsb.mb-7 button {
  min-height: 32px;
  padding: 5px 10px;
  border-radius: 9px;
  border-width: 1px;
  background: var(--hva-card-soft);
  color: var(--hva-text-muted);
  font-size: .82rem;
}

/* Main post card */
html.hva-comfortable-post body.hva-post-page article.row-x {
  grid-template-columns: 92px minmax(0, 1fr);
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--hva-card-bg);
  box-shadow: var(--shadow);
  overflow: hidden;
}

body.hva-post-page article.row-x > .g343.p-10.tac,
body.hva-post-page article.row-x > .g343.p-10.tac.g-profile {
  background: var(--hva-card-soft);
  border-right: 1px solid var(--border);
  color: var(--hva-text-muted);
}

body.hva-post-page .g-profile img,
body.hva-post-page .h-73,
body.hva-post-page .w-73 {
  width: 58px;
  height: 58px;
  border-radius: 12px;
}

body.hva-post-page .auth,
body.hva-post-page .auth a,
body.hva-post-page .badge a,
body.hva-post-page .g-profile a {
  color: var(--hva-text-strong) !important;
  font-size: .82rem;
  font-weight: 700;
}

body.hva-post-page .auth .mod::after,
body.hva-post-page .mod::after {
  display: inline-flex;
  margin-top: 5px;
  padding: 2px 7px;
  border-radius: 999px;
  font-size: .67rem;
  font-weight: 800;
}

body.hva-post-page article.row-x > .grid.gtr {
  padding: 14px 16px 16px;
  background: var(--hva-card-bg);
}

body.hva-post-page .post-header {
  margin-bottom: 8px;
  color: var(--hva-text-muted);
  font-size: .82rem;
}

/* Readable post body */
html.hva-comfortable-post body.hva-post-page .post-body {
  max-width: none;
  padding: 8px 0 0;
  color: var(--hva-text-body);
  font-size: 1rem;
  line-height: 1.82;
}

body.hva-post-page .post-body :where(p, ul, ol, blockquote, table, pre, .separator, .cta-box, .notice-card) {
  max-width: var(--hva-reading-width);
  margin-left: auto;
  margin-right: auto;
}

body.hva-post-page .post-body :where(p, li) {
  color: var(--hva-text-body);
}

body.hva-post-page .post-body :where(h2, h3, h4) {
  max-width: var(--hva-reading-width);
  margin-left: auto;
  margin-right: auto;
  color: var(--hva-text-strong);
}

body.hva-post-page .post-body h2 {
  font-size: 1.35rem;
}

body.hva-post-page .post-body h3 {
  font-size: 1.15rem;
}

body.hva-post-page .post-body a {
  color: var(--lime);
  font-weight: 650;
}

body.hva-post-page .post-body img {
  display: block;
  max-width: 100%;
  height: auto;
  margin-left: auto;
  margin-right: auto;
  border-radius: 10px;
}

body.hva-post-page .post-body .separator {
  text-align: center;
  margin-top: 18px;
  margin-bottom: 18px;
}

body.hva-post-page .post-body blockquote,
body.hva-post-page .post-body table,
body.hva-post-page .post-body pre {
  background: var(--hva-card-soft);
  border-color: var(--border);
  color: var(--hva-text-body);
}

/* Neutralize harsh pasted inline white/black blocks inside old Blogger posts */
html.hva-soft-inline-post body.hva-post-page .post-body :where(div, p, span, td, th, li)[style*="color"] {
  color: inherit !important;
}

html.hva-soft-inline-post body.hva-post-page .post-body :where(div, p, section, article, blockquote, table, td, th)[style*="background"] {
  background: transparent !important;
}

html.hva-soft-inline-post body.hva-post-page .post-body :where(div, p)[style*="background-color"] {
  background-color: transparent !important;
}

html.hva-theme-dark.hva-soft-inline-post body.hva-post-page .post-body :where(div, p, section, article, blockquote, table, td, th)[style*="white"] {
  background: transparent !important;
}

/* Make copied content blocks look intentional */
body.hva-post-page .post-body > :where(div, section):not(.toc-box):not(.cta-box):not(.separator) {
  max-width: var(--hva-reading-width);
  margin-left: auto;
  margin-right: auto;
}

body.hva-post-page .post-body .cta-box {
  margin-top: 24px;
  padding: 18px 20px;
  border: 1px solid var(--border);
  border-left: 4px solid var(--lime);
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(108,108,254,.14), rgba(52,211,153,.10));
  color: var(--hva-text-body);
}

body.hva-post-page .post-body .cta-box strong {
  color: var(--hva-text-strong);
}

body.hva-post-page .post-body .cta-box .button {
  color: #fff !important;
}

html.hva-theme-light body.hva-post-page .post-body .cta-box {
  background: linear-gradient(135deg, #eef2ff, #ecfdf5);
}

/* Light mode refinements */
html.hva-theme-light body.hva-post-page article.row-x,
html.hva-theme-light body.hva-post-page .breadcrumb-nav,
html.hva-theme-light body.hva-post-page .label-size a,
html.hva-theme-light body.hva-post-page .post-card-badge {
  box-shadow: 0 1px 2px rgba(15,23,42,.04);
}

html.hva-theme-light body.hva-post-page article.row-x > .g343.p-10.tac,
html.hva-theme-light body.hva-post-page article.row-x > .g343.p-10.tac.g-profile {
  background: #f2f5fa;
}

html.hva-theme-light body.hva-post-page .post-body {
  color: #2f3b4d;
}

html.hva-theme-light body.hva-post-page .post-body :where(p, li) {
  color: #2f3b4d;
}

/* Dark mode refinements */
html.hva-theme-dark body.hva-post-page .post-body {
  color: #d7dde8;
}

html.hva-theme-dark body.hva-post-page .post-body :where(p, li) {
  color: #d7dde8;
}

html.hva-theme-dark body.hva-post-page .post-body img {
  background: #f8fafc;
}

/* Less visual noise in post pages */
body.hva-post-page .label-size a,
body.hva-post-page .post-card-badge {
  font-size: .72rem;
}

body.hva-post-page .cloud-label-widget-content {
  gap: 6px;
}

body.hva-post-page .label-size a {
  min-height: 26px;
  padding: 3px 9px;
  opacity: .92;
}

/* Better mobile post reading */
@media (max-width: 760px) {
  body.hva-post-page main.max-w {
    width: calc(100% - 20px);
  }

  html.hva-comfortable-post body.hva-post-page article.row-x {
    grid-template-columns: 1fr;
  }

  body.hva-post-page article.row-x > .g343.p-10.tac,
  body.hva-post-page article.row-x > .g343.p-10.tac.g-profile {
    border-right: 0;
    border-bottom: 1px solid var(--border);
    text-align: left;
  }

  body.hva-post-page article.row-x > .grid.gtr {
    padding: 12px;
  }

  html.hva-compact-post-header body.hva-post-page h1.fs-1d3 {
    font-size: 1.25rem;
  }

  html.hva-comfortable-post body.hva-post-page .post-body {
    font-size: .98rem;
    line-height: 1.76;
  }

  body.hva-post-page .post-body :where(p, ul, ol, blockquote, table, pre, .separator, .cta-box, .notice-card),
  body.hva-post-page .post-body > :where(div, section):not(.toc-box):not(.cta-box):not(.separator),
  body.hva-post-page .post-body :where(h2, h3, h4) {
    max-width: 100%;
  }
}



/* =========================================================
   HVA TOC Heading SEO Polish v2.0.2.1
   Goals:
   - Softer light/dark color system
   - Neutral readable title links instead of noisy blue everywhere
   - More attractive home cards and content hierarchy
   - Full layout remains wide but readable on large screens
   ========================================================= */
:root {
  --hva-home-max-width: 1440px;
  --hva-radius-card: 14px;
  --hva-radius-soft: 12px;
  --hva-home-title-size: 1.03rem;
  --hva-home-snippet-size: .92rem;
  --hva-link: #a8adff;
  --hva-link-hover: #c8cbff;
  --hva-title: #f8fafc;
  --hva-body: #d6deea;
  --hva-soft-body: #aeb9ca;
  --hva-meta: #8d98aa;
  --hva-card: #1d2024;
  --hva-card-2: #242832;
  --hva-card-3: #2a2f3a;
  --hva-page: #111315;
  --hva-line: #343b48;
  --hva-soft-accent: rgba(108,108,254,.16);
  --hva-soft-accent-2: rgba(52,211,153,.11);
}

html.hva-theme-light {
  --lime: #5865e8;
  --hva-link: #4350c8;
  --hva-link-hover: #2532a8;
  --hva-title: #162033;
  --hva-body: #354154;
  --hva-soft-body: #5b687a;
  --hva-meta: #778397;
  --hva-card: #ffffff;
  --hva-card-2: #f7f9fd;
  --hva-card-3: #edf2f9;
  --hva-page: #f0f4f9;
  --hva-line: #dce5f2;
  --hva-soft-accent: rgba(88,101,232,.10);
  --hva-soft-accent-2: rgba(20,184,166,.10);
  --shadow: 0 14px 34px rgba(15,23,42,.075);
}

html.hva-theme-dark {
  --lime: #8588ff;
  --hva-link: #a8adff;
  --hva-link-hover: #ffffff;
  --hva-title: #f7f9ff;
  --hva-body: #d6deea;
  --hva-soft-body: #b3bdcc;
  --hva-meta: #909caf;
  --hva-card: #1b1f25;
  --hva-card-2: #232832;
  --hva-card-3: #2a303b;
  --hva-page: #101216;
  --hva-line: #353c49;
  --hva-soft-accent: rgba(133,136,255,.15);
  --hva-soft-accent-2: rgba(45,212,191,.10);
  --shadow: 0 18px 42px rgba(0,0,0,.32);
}

html.hva-theme-light body,
html.hva-theme-dark body {
  background: var(--hva-page);
  color: var(--hva-body);
}

html.hva-theme-light a,
html.hva-theme-dark a {
  color: var(--hva-link);
}

html.hva-theme-light a:hover,
html.hva-theme-dark a:hover {
  color: var(--hva-link-hover);
}

/* Keep full screen useful, but avoid ultra-wide unreadable rows */
html.hva-layout-full.hva-home-readable-width body.fv .max-w {
  max-width: var(--hva-home-max-width) !important;
}

html.hva-layout-full.hva-home-readable-width body.fv .featured-grid {
  grid-template-columns: repeat(auto-fit, minmax(270px, 1fr));
}

html.hva-layout-full.hva-home-readable-width body.fv .home-category-grid {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

/* Global home readability */
body.fv {
  letter-spacing: .002em;
}

body.fv .section-title,
body.fv .home-category-title,
body.fv .featured-title,
body.fv .latest-title,
body.fv .home-category-card-title {
  color: var(--hva-title) !important;
  text-shadow: none !important;
}

html.hva-neutral-title-links body.fv .featured-title a,
html.hva-neutral-title-links body.fv .latest-title a,
html.hva-neutral-title-links body.fv .home-category-card-title,
html.hva-neutral-title-links body.fv .home-category-card-title:visited,
html.hva-neutral-title-links body.fv .section-title a,
html.hva-neutral-title-links body.fv .home-category-title a {
  color: var(--hva-title) !important;
}

html.hva-neutral-title-links body.fv .featured-title a:hover,
html.hva-neutral-title-links body.fv .latest-title a:hover,
html.hva-neutral-title-links body.fv .home-category-card-title:hover {
  color: var(--hva-link-hover) !important;
  text-decoration: none;
}

body.fv .featured-snippet,
body.fv .latest-snippet,
body.fv .home-category-card-snippet,
body.fv .section-note,
body.fv .home-category-more {
  color: var(--hva-soft-body) !important;
}

body.fv .section-note,
body.fv .home-category-more {
  font-weight: 600;
}

/* Header/menu visual cleanup */
body.fv header.max-w {
  margin-bottom: 18px;
}

html.hva-theme-light .nav-main,
html.hva-theme-light .nav-meta,
html.hva-theme-light #PageList1 .widget-content,
html.hva-theme-light .g262 {
  background: var(--hva-card) !important;
  border-color: var(--hva-line) !important;
}

html.hva-theme-dark .nav-main,
html.hva-theme-dark .nav-meta,
html.hva-theme-dark #PageList1 .widget-content,
html.hva-theme-dark .g262 {
  background: var(--hva-card) !important;
  border-color: var(--hva-line) !important;
}

.nav-main a,
.nav-meta a {
  font-weight: 650;
  font-size: .86rem;
}

/* Notice bar: less harsh, more readable */
html.hva-soft-notice-bar .g4d0,
html.hva-soft-notice-bar .notice-card.g4d0,
html.hva-soft-notice-bar [class*="g4d0"] {
  border: 1px solid rgba(244,63,94,.32) !important;
  border-left: 4px solid #f43f5e !important;
  border-radius: 12px !important;
  box-shadow: none !important;
}

html.hva-theme-light.hva-soft-notice-bar .g4d0,
html.hva-theme-light.hva-soft-notice-bar [class*="g4d0"] {
  background: #fff1f3 !important;
  color: #9f1239 !important;
}

html.hva-theme-light.hva-soft-notice-bar .ce5b,
html.hva-theme-light.hva-soft-notice-bar .g4d0 * {
  color: #9f1239 !important;
}

html.hva-theme-dark.hva-soft-notice-bar .g4d0,
html.hva-theme-dark.hva-soft-notice-bar [class*="g4d0"] {
  background: rgba(127,29,29,.22) !important;
  color: #fecdd3 !important;
}

html.hva-theme-dark.hva-soft-notice-bar .ce5b,
html.hva-theme-dark.hva-soft-notice-bar .g4d0 * {
  color: #fecdd3 !important;
}

/* Search box */
body.fv .hva-search-box {
  border-radius: var(--hva-radius-card);
  background: linear-gradient(135deg, var(--hva-card), var(--hva-card-2));
  border-color: var(--hva-line);
  box-shadow: 0 1px 2px rgba(0,0,0,.04);
}

body.fv .hva-search-box input {
  min-height: 46px;
  border-radius: 11px;
  background: var(--hva-card);
  border-color: var(--hva-line);
  color: var(--hva-title);
  font-size: .94rem;
}

body.fv .hva-search-box input::placeholder {
  color: var(--hva-meta);
}

body.fv .hva-search-box button {
  min-height: 46px;
  border-radius: 11px;
  background: linear-gradient(135deg, var(--lime), #14b8a6);
  box-shadow: 0 8px 20px rgba(88,101,232,.18);
}

/* Label cloud */
html.hva-compact-label-cloud .label-size a,
.hva-label-toggle {
  border-color: var(--hva-line) !important;
  background: var(--hva-card-2) !important;
  color: var(--hva-soft-body) !important;
  font-weight: 650;
}

html.hva-compact-label-cloud .label-size a:hover,
.hva-label-toggle:hover {
  border-color: var(--lime) !important;
  background: var(--hva-soft-accent) !important;
  color: var(--hva-title) !important;
}

/* Section blocks */
body.fv .section-head,
body.fv .home-category-head {
  min-height: 46px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--hva-line);
  background: linear-gradient(135deg, var(--hva-card-2), var(--hva-card));
}

body.fv .section-title,
body.fv .home-category-title {
  font-size: 1rem;
  font-weight: 850;
  letter-spacing: -.005em;
}

body.fv .home-category-block,
body.fv .featured-card,
body.fv .latest-list,
body.fv #HTML1,
body.fv #HTML4 {
  border-color: var(--hva-line) !important;
  background: var(--hva-card) !important;
  border-radius: var(--hva-radius-card);
  box-shadow: 0 1px 2px rgba(0,0,0,.035);
}

html.hva-theme-dark body.fv .home-category-block,
html.hva-theme-dark body.fv .featured-card,
html.hva-theme-dark body.fv .latest-list {
  box-shadow: 0 10px 28px rgba(0,0,0,.16);
}

/* Category discovery blocks */
body.fv .home-category-sections {
  gap: 18px;
}

body.fv .home-category-grid {
  gap: 12px;
  padding: 13px;
}

body.fv .home-category-card {
  border: 1px solid transparent;
  border-radius: 12px;
  padding: 8px;
  background: transparent;
}

body.fv .home-category-card:hover {
  background: var(--hva-card-2) !important;
  border-color: var(--hva-line);
  transform: translateY(-1px);
}

body.fv .home-category-thumb {
  border-radius: 10px;
  background: var(--hva-card-3);
}

body.fv .home-category-card-title {
  font-size: .96rem;
  line-height: 1.38;
  font-weight: 800;
}

body.fv .home-category-card-snippet {
  font-size: .87rem;
  line-height: 1.5;
}

/* Featured cards */
body.fv .featured-grid {
  gap: 16px;
  padding: 14px;
}

body.fv .featured-card {
  overflow: hidden;
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}

body.fv .featured-card:hover {
  transform: translateY(-2px);
  border-color: rgba(88,101,232,.45) !important;
  box-shadow: var(--shadow);
}

body.fv .featured-body {
  gap: 8px;
  padding: 13px 14px 14px;
}

body.fv .featured-title {
  font-size: var(--hva-home-title-size);
  line-height: 1.42;
  font-weight: 850;
}

body.fv .featured-snippet {
  font-size: var(--hva-home-snippet-size);
  line-height: 1.6;
}

/* Latest list: turn the list into readable rows */
body.fv .latest-list {
  overflow: hidden;
}

body.fv .latest-card {
  grid-template-columns: 92px minmax(0,1fr);
  gap: 14px;
  padding: 15px 16px;
  border-bottom-color: var(--hva-line);
  background: var(--hva-card);
  transition: background .16s ease, transform .16s ease;
}

body.fv .latest-card:hover {
  background: var(--hva-card-2) !important;
}

body.fv .latest-thumb-link {
  border-radius: 12px;
  background: var(--hva-card-3);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.04);
}

body.fv .latest-thumb {
  width: 92px;
  border-radius: 12px;
}

body.fv .latest-title {
  margin-bottom: 4px;
  font-size: clamp(1rem, .94rem + .16vw, 1.12rem);
  line-height: 1.42;
  font-weight: 850;
}

body.fv .latest-snippet {
  margin-top: 5px;
  font-size: .93rem;
  line-height: 1.58;
  color: var(--hva-soft-body) !important;
}

body.fv .post-card-cta {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  margin-top: 5px;
  color: var(--hva-link) !important;
  font-size: .82rem;
  font-weight: 800;
}

body.fv .post-card-cta:hover {
  color: var(--hva-link-hover) !important;
  text-decoration: none;
}

/* Badges */
body.fv .post-card-badges {
  margin: 3px 0 4px;
  gap: 6px;
}

body.fv .post-card-badge,
body.fv .badge-new {
  border-radius: 999px;
  font-weight: 750;
}

body.fv .post-card-badge {
  background: var(--hva-card-2);
  border-color: var(--hva-line);
  color: var(--hva-soft-body) !important;
}

body.fv .post-card-badge:hover {
  background: var(--hva-soft-accent);
  border-color: var(--lime);
  color: var(--hva-title) !important;
}

body.fv .badge-new {
  background: linear-gradient(135deg, #c026d3, #7c3aed);
  color: #fff !important;
  box-shadow: 0 6px 16px rgba(124,58,237,.22);
}

/* Pagination/footer cleanup */
body.fv .showpageOf,
body.fv .displaypageNum,
body.fv .pagecurrent,
body.fv .firstpage {
  border-color: var(--hva-line) !important;
  background: var(--hva-card-2) !important;
  color: var(--hva-soft-body) !important;
  font-weight: 700;
}

body.fv .pagecurrent {
  background: var(--lime) !important;
  color: #fff !important;
}

body.fv footer,
body.fv footer .g262 {
  color: var(--hva-soft-body);
}

/* Design density options */
html.hva-home-compact body.fv .featured-grid { gap: 12px; padding: 12px; }
html.hva-home-compact body.fv .latest-card { padding: 11px 12px; }
html.hva-home-compact body.fv .latest-title { font-size: .98rem; }
html.hva-home-compact body.fv .latest-snippet { font-size: .88rem; -webkit-line-clamp: 1; }

html.hva-home-comfortable body.fv .latest-snippet,
html.hva-home-comfortable body.fv .featured-snippet {
  -webkit-line-clamp: 2;
}

/* Mobile */
@media (max-width: 760px) {
  body.fv .featured-grid { grid-template-columns: 1fr; padding: 12px; }
  body.fv .latest-card { grid-template-columns: 74px minmax(0,1fr); gap: 11px; padding: 12px; }
  body.fv .latest-thumb { width: 74px; }
  body.fv .latest-title { font-size: .98rem; }
  body.fv .latest-snippet { font-size: .88rem; -webkit-line-clamp: 2; }
  body.fv .section-head,
  body.fv .home-category-head { padding: 9px 11px; }
  .nav-main a,
  .nav-meta a { font-size: .84rem; }
}



/* =========================================================
   HVA TOC, Heading & Article SEO Polish v2.0.2.1
   Muc tieu:
   - TOC ro rang hon, co active section, co collapse tren mobile
   - Heading de quet hon, co anchor link noi bo
   - Toi uu anh cu trong bai: lazy loading, alt fallback, decoding async
   - Giu noi dung bai viet de doc hon va tang lien ket noi bo theo section
   ========================================================= */
:root {
  --hva-toc-radius: 14px;
  --hva-heading-anchor-size: 1.05em;
}

html.hva-enhanced-toc body.hva-post-page .toc-box {
  display: none;
  max-width: var(--hva-reading-width);
  margin: 6px auto 24px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--hva-toc-radius);
  background: var(--hva-card-soft);
  color: var(--hva-text-body);
  overflow: hidden;
  box-shadow: 0 8px 24px rgba(0,0,0,.10);
}

html.hva-enhanced-toc body.hva-post-page .toc-box.active {
  display: block;
}

body.hva-post-page .toc-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
  background: linear-gradient(135deg, rgba(108,108,254,.13), rgba(52,211,153,.08));
}

body.hva-post-page .toc-title {
  margin: 0;
  color: var(--hva-text-strong);
  font-size: .94rem;
  font-weight: 850;
  letter-spacing: -.005em;
}

body.hva-post-page .toc-title::before {
  content: "☰";
  display: inline-flex;
  margin-right: 7px;
  color: var(--lime);
  font-weight: 900;
}

body.hva-post-page .toc-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 28px;
  padding: 3px 9px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(255,255,255,.04);
  color: var(--hva-text-muted);
  font-size: .75rem;
  font-weight: 750;
  cursor: pointer;
}

body.hva-post-page .toc-toggle:hover {
  border-color: var(--lime);
  color: var(--hva-text-strong);
}

body.hva-post-page .toc-list {
  margin: 0;
  padding: 8px;
  list-style: none;
  counter-reset: hvaToc;
}

body.hva-post-page .toc-list li {
  margin: 0;
}

body.hva-post-page .toc-list a {
  display: grid;
  grid-template-columns: 24px minmax(0,1fr);
  gap: 8px;
  align-items: start;
  padding: 7px 8px;
  border-radius: 10px;
  color: var(--hva-text-body);
  font-size: .88rem;
  line-height: 1.45;
  font-weight: 650;
  text-decoration: none;
}

body.hva-post-page .toc-list a:hover,
body.hva-post-page .toc-list li.is-active > a {
  background: rgba(108,108,254,.12);
  color: var(--hva-text-strong);
}

body.hva-post-page .toc-list .toc-h2 > a::before {
  counter-increment: hvaToc;
  content: counter(hvaToc);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 999px;
  background: rgba(108,108,254,.16);
  color: var(--lime);
  font-size: .74rem;
  font-weight: 900;
}

body.hva-post-page .toc-list .toc-h3 > a {
  grid-template-columns: 18px minmax(0,1fr);
  padding-top: 5px;
  padding-bottom: 5px;
  padding-left: 34px;
  color: var(--hva-text-muted);
  font-size: .82rem;
  font-weight: 600;
}

body.hva-post-page .toc-list .toc-h3 > a::before {
  content: "›";
  display: inline-flex;
  justify-content: center;
  color: var(--lime);
  opacity: .8;
}

body.hva-post-page .toc-box.is-collapsed .toc-list {
  display: none;
}

body.hva-post-page .toc-box.is-collapsed .toc-head {
  border-bottom: 0;
}

html.hva-improved-headings body.hva-post-page .post-body h2,
html.hva-improved-headings body.hva-post-page .post-body h3,
html.hva-improved-headings body.hva-post-page .post-body h4 {
  position: relative;
  scroll-margin-top: 92px;
  color: var(--hva-text-strong);
  letter-spacing: -.012em;
}

html.hva-improved-headings body.hva-post-page .post-body h2 {
  margin-top: 2.25em;
  margin-bottom: .72em;
  padding-top: .85em;
  border-top: 1px solid var(--border);
  font-size: clamp(1.34rem, 1.12rem + .65vw, 1.72rem);
  line-height: 1.28;
  font-weight: 900;
}

html.hva-improved-headings body.hva-post-page .post-body h2::before {
  content: "";
  position: absolute;
  left: 0;
  top: -.5px;
  width: 58px;
  height: 2px;
  border-radius: 999px;
  background: var(--lime);
}

html.hva-improved-headings body.hva-post-page .post-body h3 {
  margin-top: 1.6em;
  margin-bottom: .58em;
  padding-left: 12px;
  border-left: 3px solid var(--lime);
  font-size: clamp(1.08rem, 1rem + .25vw, 1.24rem);
  line-height: 1.34;
  font-weight: 850;
}

html.hva-improved-headings body.hva-post-page .post-body h4 {
  margin-top: 1.35em;
  margin-bottom: .45em;
  font-size: 1.02rem;
  line-height: 1.38;
  font-weight: 800;
}

body.hva-post-page .post-body .hva-heading-anchor {
  margin-left: 8px;
  color: var(--hva-text-muted) !important;
  font-size: .78em;
  font-weight: 800;
  opacity: 0;
  text-decoration: none;
  transition: opacity .16s ease, color .16s ease;
}

body.hva-post-page .post-body :where(h2,h3,h4):hover .hva-heading-anchor,
body.hva-post-page .post-body .hva-heading-anchor:focus {
  opacity: 1;
  color: var(--lime) !important;
}

body.hva-post-page .post-body :where(p, li) {
  font-size: 1.015rem;
}

body.hva-post-page .post-body strong,
body.hva-post-page .post-body b {
  color: var(--hva-text-strong);
  font-weight: 850;
}

body.hva-post-page .post-body img[loading="lazy"] {
  content-visibility: auto;
}

body.hva-post-page .post-body .separator + h2,
body.hva-post-page .post-body .separator + h3 {
  margin-top: 1.2em;
}

.hva-reading-progress {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 9999;
  width: 100%;
  height: 3px;
  pointer-events: none;
  background: transparent;
}

.hva-reading-progress > span {
  display: block;
  width: 0;
  height: 100%;
  background: linear-gradient(90deg, var(--lime), #34d399);
  box-shadow: 0 0 10px rgba(108,108,254,.45);
}

html.hva-hide-reading-progress .hva-reading-progress {
  display: none !important;
}

html.hva-theme-light body.hva-post-page .toc-box {
  box-shadow: 0 8px 24px rgba(15,23,42,.06);
}

html.hva-theme-light body.hva-post-page .toc-head {
  background: linear-gradient(135deg, #eef2ff, #ecfdf5);
}

html.hva-theme-light body.hva-post-page .toc-list a:hover,
html.hva-theme-light body.hva-post-page .toc-list li.is-active > a {
  background: #eef2ff;
}

@media (max-width: 760px) {
  body.hva-post-page .toc-head {
    padding: 10px 11px;
  }
  body.hva-post-page .toc-list {
    padding: 7px;
  }
  body.hva-post-page .toc-list a {
    font-size: .84rem;
  }
  body.hva-post-page .post-body :where(p, li) {
    font-size: .98rem;
  }
  html.hva-improved-headings body.hva-post-page .post-body h2 {
    font-size: 1.24rem;
  }
}



/* =========================================================
   HVA Layout Clarity & Static Page Polish v2.0.2.2
   Goals:
   - Static pages look like clean information pages, not forum posts
   - Remove noisy author/comment/category elements from pages when enabled
   - Clearer content container, spacing, title hierarchy and footer area
   ========================================================= */
:root {
  --hva-static-page-width: 960px;
  --hva-static-reading-width: 760px;
}

/* Generic page spacing cleanup */
html.hva-reduce-page-top-spacing body.hva-static-page header.max-w {
  margin-bottom: 20px;
}

html.hva-reduce-page-top-spacing body.hva-static-page main.max-w {
  margin-top: 0;
}

body.hva-static-page #hva-02-status-optional {
  display: none !important;
}

/* Hide category cloud on static pages to avoid confusing page intent */
html.hva-hide-static-labels body.hva-static-page #Label1,
html.hva-hide-static-labels body.hva-static-page .Label {
  display: none !important;
}

/* Static page max width: compact, centered and readable */
html.hva-page-clear-layout body.hva-static-page main.max-w {
  max-width: var(--hva-static-page-width) !important;
  width: min(calc(100% - 32px), var(--hva-static-page-width));
  color: var(--hva-body, var(--hva-text-body));
}

html.hva-page-clear-layout body.hva-static-page #main {
  gap: 14px;
}

/* Page title as a clear hero title */
html.hva-page-clear-layout body.hva-static-page h1.fs-1d3 {
  max-width: var(--hva-static-reading-width);
  margin: 0 auto 14px;
  color: var(--hva-title, var(--hva-text-strong));
  font-size: clamp(1.9rem, 1.45rem + 1.2vw, 2.55rem);
  font-weight: 900;
  line-height: 1.2;
  letter-spacing: -.025em;
}

html.hva-page-clear-layout body.hva-static-page h1.fs-1d3::after {
  content: "";
  display: block;
  width: 72px;
  height: 3px;
  margin-top: 12px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--lime), #14b8a6);
}

/* Remove forum controls on static pages */
html.hva-hide-static-comment-tools body.hva-static-page .flex.jcsb.mb-7,
html.hva-hide-static-comment-tools body.hva-static-page .comment-lock,
html.hva-hide-static-comment-tools body.hva-static-page [id='myList1'] {
  display: none !important;
}

/* Static page card */
html.hva-page-clear-layout body.hva-static-page article.row-x {
  display: block;
  max-width: var(--hva-static-reading-width);
  margin: 0 auto 18px;
  border: 1px solid var(--hva-line, var(--border));
  border-radius: 18px;
  background: var(--hva-card, var(--hva-card-bg));
  box-shadow: var(--shadow);
  overflow: hidden;
}

html.hva-theme-light.hva-page-clear-layout body.hva-static-page article.row-x {
  box-shadow: 0 16px 42px rgba(15,23,42,.075);
}

html.hva-theme-dark.hva-page-clear-layout body.hva-static-page article.row-x {
  box-shadow: 0 18px 44px rgba(0,0,0,.28);
}

/* Hide forum author column on static pages */
html.hva-hide-static-author body.hva-static-page article.row-x > .g343.p-10.tac,
html.hva-hide-static-author body.hva-static-page article.row-x > .g343.p-10.tac.g-profile,
html.hva-hide-static-author body.hva-static-page article.row-x > aside,
html.hva-hide-static-author body.hva-static-page article.row-x > .g-profile {
  display: none !important;
}

html.hva-page-clear-layout body.hva-static-page article.row-x > .grid.gtr {
  padding: clamp(22px, 3vw, 34px);
  background: var(--hva-card, var(--hva-card-bg));
}

html.hva-hide-static-meta body.hva-static-page .post-header,
html.hva-hide-static-meta body.hva-static-page .post-meta-line,
html.hva-hide-static-meta body.hva-static-page .post-meta,
html.hva-hide-static-meta body.hva-static-page .post-labels,
html.hva-hide-static-meta body.hva-static-page .feed-links,
html.hva-hide-static-meta body.hva-static-page .blog-feeds {
  display: none !important;
}

html.hva-clean-static-footer body.hva-static-page article.row-x footer.jsr {
  display: none !important;
}

/* Static page body typography */
html.hva-page-clear-layout body.hva-static-page .post-body {
  padding: 0;
  max-width: none;
  color: var(--hva-body, var(--hva-text-body));
  font-size: 1.04rem;
  line-height: 1.86;
}

html.hva-page-clear-layout body.hva-static-page .post-body :where(p, ul, ol, blockquote, table, pre, .separator, .notice-card, .cta-box, div) {
  max-width: 100%;
}

html.hva-page-clear-layout body.hva-static-page .post-body p {
  margin: 0 0 1.1em;
}

html.hva-page-clear-layout body.hva-static-page .post-body :where(h2,h3,h4) {
  color: var(--hva-title, var(--hva-text-strong));
  line-height: 1.32;
  letter-spacing: -.012em;
}

html.hva-page-clear-layout body.hva-static-page .post-body h2 {
  margin: 1.65em 0 .65em;
  padding-top: .65em;
  border-top: 1px solid var(--hva-line, var(--border));
  font-size: clamp(1.28rem, 1.12rem + .55vw, 1.58rem);
  font-weight: 900;
}

html.hva-page-clear-layout body.hva-static-page .post-body h3 {
  margin: 1.35em 0 .55em;
  padding-left: 12px;
  border-left: 3px solid var(--lime);
  font-size: 1.12rem;
  font-weight: 850;
}

html.hva-page-clear-layout body.hva-static-page .post-body a {
  color: var(--hva-link, var(--lime));
  font-weight: 700;
  text-decoration-thickness: .08em;
  text-underline-offset: .18em;
}

html.hva-page-clear-layout body.hva-static-page .post-body strong,
html.hva-page-clear-layout body.hva-static-page .post-body b {
  color: var(--hva-title, var(--hva-text-strong));
  font-weight: 850;
}

html.hva-page-clear-layout body.hva-static-page .post-body blockquote,
html.hva-page-clear-layout body.hva-static-page .post-body .notice-card {
  margin: 18px 0;
  padding: 14px 16px;
  border: 1px solid var(--hva-line, var(--border));
  border-left: 4px solid var(--lime);
  border-radius: 14px;
  background: var(--hva-card-2, var(--hva-card-soft));
}

html.hva-theme-light.hva-page-clear-layout body.hva-static-page .post-body {
  color: #334155;
}

html.hva-theme-dark.hva-page-clear-layout body.hva-static-page .post-body {
  color: #d6deea;
}

/* Footer / bottom links become a compact footer bar on static pages */
html.hva-page-clear-layout body.hva-static-page footer.max-w,
html.hva-page-clear-layout body.hva-static-page body > footer {
  max-width: var(--hva-static-page-width) !important;
}

html.hva-page-clear-layout body.hva-static-page #PageList2,
html.hva-page-clear-layout body.hva-static-page footer .g262 {
  max-width: var(--hva-static-page-width);
  margin-left: auto;
  margin-right: auto;
  border-radius: 12px;
  background: var(--hva-card, var(--hva-card-bg)) !important;
  border: 1px solid var(--hva-line, var(--border));
}

/* Header alignment with fixed/full modes: avoid feeling detached */
html.hva-page-clear-layout body.hva-static-page header.max-w,
html.hva-page-clear-layout body.hva-static-page footer.max-w {
  width: min(calc(100% - 32px), var(--hva-fixed-width, 1200px));
}

html.hva-layout-full.hva-page-clear-layout body.hva-static-page header.max-w,
html.hva-layout-full.hva-page-clear-layout body.hva-static-page footer.max-w {
  width: min(calc(100% - 32px), var(--hva-home-max-width, 1440px));
}

/* Reduce visual noise from tiny top nav lines on clean pages */
html.hva-page-clear-layout body.hva-static-page .nav-main,
html.hva-page-clear-layout body.hva-static-page .nav-meta {
  border-color: var(--hva-line, var(--border)) !important;
}

/* Optional page intro card inserted by JS for pages with very short content */
.hva-page-intro {
  max-width: var(--hva-static-reading-width);
  margin: 0 auto 16px;
  padding: 13px 16px;
  border: 1px solid var(--hva-line, var(--border));
  border-radius: 14px;
  background: linear-gradient(135deg, var(--hva-soft-accent), var(--hva-soft-accent-2));
  color: var(--hva-body, var(--hva-text-body));
  font-size: .94rem;
  line-height: 1.6;
}

/* Better page layout on mobile */
@media (max-width: 760px) {
  html.hva-page-clear-layout body.hva-static-page main.max-w,
  html.hva-page-clear-layout body.hva-static-page header.max-w,
  html.hva-page-clear-layout body.hva-static-page footer.max-w {
    width: calc(100% - 20px);
  }

  html.hva-page-clear-layout body.hva-static-page h1.fs-1d3 {
    font-size: 1.65rem;
  }

  html.hva-page-clear-layout body.hva-static-page article.row-x {
    max-width: 100%;
    border-radius: 14px;
  }

  html.hva-page-clear-layout body.hva-static-page article.row-x > .grid.gtr {
    padding: 18px;
  }

  html.hva-page-clear-layout body.hva-static-page .post-body {
    font-size: .98rem;
    line-height: 1.78;
  }
}


/* =========================================================
   HVA Fixed 1920 + Clean Responsive + Static Page v2.0.2.3
   Goals:
   - Remove Full/Fix layout switch; keep only Light/Dark
   - Desktop canvas maxes at 1920px, centered on ultra-wide screens
   - Tablet/mobile use dedicated responsive spacing
   - Static pages become clean information pages, not forum cards
   ========================================================= */
:root {
  --hva-site-width: 1920px;
  --hva-shell-gap: 16px;
  --hva-static-page-width: 1040px;
  --hva-static-reading-width: 820px;
  --hva-clean-radius: 16px;
}

html.hva-fixed-1920 .max-w {
  max-width: var(--hva-site-width) !important;
  width: 100%;
}

html.hva-fixed-1920 header.max-w,
html.hva-fixed-1920 main.max-w,
html.hva-fixed-1920 footer.max-w {
  padding-left: var(--hva-shell-gap);
  padding-right: var(--hva-shell-gap);
}

html.hva-fixed-1920 .header-widget,
html.hva-fixed-1920 .nav-main,
html.hva-fixed-1920 .nav-meta,
html.hva-fixed-1920 .hva-search-box,
html.hva-fixed-1920 #hva-02-status-optional,
html.hva-fixed-1920 main.max-w > .section,
html.hva-fixed-1920 footer.max-w > * {
  max-width: var(--hva-site-width);
  margin-left: auto;
  margin-right: auto;
}

@media (min-width: 1930px) {
  html.hva-fixed-1920 body {
    background-image:
      radial-gradient(circle at 50% 0, rgba(108,108,254,.08), transparent 32rem),
      linear-gradient(90deg, rgba(255,255,255,.025), transparent 18%, transparent 82%, rgba(255,255,255,.025));
  }
  html.hva-theme-light.hva-fixed-1920 body {
    background-image:
      radial-gradient(circle at 50% 0, rgba(59,130,246,.10), transparent 34rem),
      linear-gradient(90deg, rgba(15,23,42,.04), transparent 18%, transparent 82%, rgba(15,23,42,.04));
  }
}

/* Remove Full/Fix switch; retain compact Light/Dark only */
.hva-display-switch button[data-hva-action="layout"] {
  display: none !important;
}
.hva-display-switch {
  padding: 4px !important;
  gap: 0 !important;
  border-radius: 999px !important;
}
.hva-display-switch button {
  min-width: 54px !important;
  border-radius: 999px !important;
}

/* Cleaner static page shell */
html.hva-page-clear-layout body.hva-static-page {
  background-color: var(--hva-bg, var(--dark));
}

html.hva-page-clear-layout body.hva-static-page #hva-02-status-optional,
html.hva-page-clear-layout body.hva-static-page #Label1,
html.hva-page-clear-layout body.hva-static-page .Label,
html.hva-page-clear-layout body.hva-static-page .feed-links,
html.hva-page-clear-layout body.hva-static-page .blog-feeds {
  display: none !important;
}

html.hva-page-clear-layout body.hva-static-page header.max-w {
  margin-bottom: clamp(18px, 2.4vw, 34px) !important;
}

html.hva-page-clear-layout body.hva-static-page main.max-w {
  max-width: var(--hva-site-width) !important;
  width: 100% !important;
  margin-top: 0 !important;
  margin-bottom: 22px !important;
  color: var(--hva-body, var(--hva-text-body));
}

html.hva-page-clear-layout body.hva-static-page #main {
  display: block !important;
  max-width: var(--hva-static-page-width);
  margin-left: auto;
  margin-right: auto;
  padding: clamp(18px, 2.4vw, 34px);
  border: 1px solid var(--hva-line, var(--border));
  border-radius: 22px;
  background: linear-gradient(180deg, rgba(255,255,255,.035), rgba(255,255,255,.012));
  box-shadow: 0 18px 52px rgba(0,0,0,.22);
}

html.hva-theme-light.hva-page-clear-layout body.hva-static-page #main {
  background: #ffffff;
  box-shadow: 0 18px 48px rgba(15,23,42,.075);
}

/* Static title: less decorative, clearer hierarchy */
html.hva-page-clear-layout body.hva-static-page h1.fs-1d3 {
  max-width: var(--hva-static-reading-width);
  margin: 0 auto 18px !important;
  color: var(--hva-title, var(--hva-text-strong));
  font-size: clamp(1.75rem, 1.36rem + 1.1vw, 2.35rem) !important;
  font-weight: 850 !important;
  line-height: 1.18 !important;
  letter-spacing: -.025em;
  text-align: left;
  text-shadow: none !important;
}

html.hva-page-clear-layout body.hva-static-page h1.fs-1d3::after {
  width: 54px !important;
  height: 3px !important;
  margin: 12px 0 0 !important;
  opacity: .9;
}

/* Flatten Blogger/forum chrome inside static pages */
html.hva-page-clear-layout body.hva-static-page .breadcrumb-nav,
html.hva-page-clear-layout body.hva-static-page .flex.jcsb.mb-7,
html.hva-page-clear-layout body.hva-static-page .comment-lock,
html.hva-page-clear-layout body.hva-static-page [id='myList1'],
html.hva-page-clear-layout body.hva-static-page article.row-x > .g343.p-10.tac,
html.hva-page-clear-layout body.hva-static-page article.row-x > .g343.p-10.tac.g-profile,
html.hva-page-clear-layout body.hva-static-page article.row-x > aside,
html.hva-page-clear-layout body.hva-static-page article.row-x > .g-profile,
html.hva-page-clear-layout body.hva-static-page article.row-x > .grid.gtr > header.flex.jcsb,
html.hva-page-clear-layout body.hva-static-page article.row-x footer.jsr,
html.hva-page-clear-layout body.hva-static-page .post-header,
html.hva-page-clear-layout body.hva-static-page .post-meta-line,
html.hva-page-clear-layout body.hva-static-page .post-meta,
html.hva-page-clear-layout body.hva-static-page .post-labels {
  display: none !important;
}

html.hva-page-clear-layout body.hva-static-page article.row-x {
  display: block !important;
  max-width: var(--hva-static-reading-width) !important;
  margin: 0 auto !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  overflow: visible !important;
}

html.hva-page-clear-layout body.hva-static-page article.row-x > .grid.gtr {
  display: block !important;
  padding: 0 !important;
  background: transparent !important;
}

html.hva-page-clear-layout body.hva-static-page .post-body {
  max-width: var(--hva-static-reading-width) !important;
  margin: 0 auto !important;
  padding: 0 !important;
  color: var(--hva-body, var(--hva-text-body));
  font-size: 1.04rem !important;
  line-height: 1.82 !important;
}

html.hva-page-clear-layout body.hva-static-page .post-body :where(p, li) {
  color: var(--hva-body, var(--hva-text-body));
}

html.hva-page-clear-layout body.hva-static-page .post-body p {
  margin: 0 0 1rem !important;
}

html.hva-page-clear-layout body.hva-static-page .post-body ul,
html.hva-page-clear-layout body.hva-static-page .post-body ol {
  margin: .75rem 0 1.25rem;
  padding-left: 1.35rem;
}

html.hva-page-clear-layout body.hva-static-page .post-body li + li {
  margin-top: .28rem;
}

html.hva-page-clear-layout body.hva-static-page .post-body h2 {
  margin: 1.8rem 0 .75rem !important;
  padding-top: 1.1rem !important;
  border-top: 1px solid var(--hva-line, var(--border));
  color: var(--hva-title, var(--hva-text-strong));
  font-size: clamp(1.22rem, 1.05rem + .55vw, 1.48rem) !important;
  font-weight: 850 !important;
  letter-spacing: -.015em;
}

html.hva-page-clear-layout body.hva-static-page .post-body h2:first-child {
  margin-top: .2rem !important;
  padding-top: 0 !important;
  border-top: 0 !important;
}

html.hva-page-clear-layout body.hva-static-page .post-body h3 {
  margin: 1.4rem 0 .55rem !important;
  padding-left: 11px;
  border-left: 3px solid var(--lime);
  color: var(--hva-title, var(--hva-text-strong));
  font-size: 1.08rem !important;
  font-weight: 800 !important;
}

html.hva-page-clear-layout body.hva-static-page .post-body strong,
html.hva-page-clear-layout body.hva-static-page .post-body b {
  color: var(--hva-title, var(--hva-text-strong));
  font-weight: 800;
}

html.hva-page-clear-layout body.hva-static-page .post-body :where(blockquote, .notice-card, .cta-box) {
  margin: 18px 0 !important;
  padding: 15px 17px !important;
  border-radius: 14px !important;
  border: 1px solid var(--hva-line, var(--border)) !important;
  border-left: 4px solid var(--lime) !important;
  background: var(--hva-card-2, var(--hva-card-soft)) !important;
}

html.hva-page-clear-layout body.hva-static-page #PageList2,
html.hva-page-clear-layout body.hva-static-page footer .g262 {
  max-width: var(--hva-static-page-width) !important;
  border-radius: 12px !important;
  opacity: .88;
}

/* Desktop/tablet/mobile responsive rules */
@media (max-width: 1180px) {
  :root { --hva-shell-gap: 14px; }
  html.hva-fixed-1920 .home-category-grid,
  html.hva-fixed-1920 .featured-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  :root { --hva-shell-gap: 12px; }
  html.hva-fixed-1920 .header-widget {
    min-height: 82px;
    padding: 14px;
  }
  html.hva-fixed-1920 .nav-main,
  html.hva-fixed-1920 .nav-meta {
    font-size: .84rem;
  }
  html.hva-page-clear-layout body.hva-static-page #main {
    max-width: min(100%, 760px);
    padding: 22px;
    border-radius: 18px;
  }
  html.hva-page-clear-layout body.hva-static-page .post-body {
    font-size: 1rem !important;
    line-height: 1.76 !important;
  }
}

@media (max-width: 650px) {
  :root { --hva-shell-gap: 10px; }
  html.hva-fixed-1920 header.max-w,
  html.hva-fixed-1920 main.max-w,
  html.hva-fixed-1920 footer.max-w {
    padding-left: 10px;
    padding-right: 10px;
  }
  html.hva-fixed-1920 .header-widget {
    min-height: 70px;
    padding: 10px 12px;
    border-radius: 0 0 12px 12px;
  }
  html.hva-fixed-1920 .nav-main {
    overflow-x: auto;
    flex-wrap: nowrap;
    scrollbar-width: none;
  }
  html.hva-fixed-1920 .nav-main::-webkit-scrollbar { display: none; }
  html.hva-fixed-1920 .hva-search-box form {
    grid-template-columns: 1fr;
  }
  html.hva-fixed-1920 .home-category-grid,
  html.hva-fixed-1920 .featured-grid {
    grid-template-columns: 1fr;
  }
  html.hva-fixed-1920 .latest-card {
    grid-template-columns: 64px minmax(0,1fr) !important;
    gap: 10px !important;
  }
  html.hva-fixed-1920 .latest-thumb {
    width: 64px !important;
  }
  html.hva-page-clear-layout body.hva-static-page header.max-w {
    margin-bottom: 14px !important;
  }
  html.hva-page-clear-layout body.hva-static-page #main {
    padding: 18px 15px;
    border-radius: 16px;
  }
  html.hva-page-clear-layout body.hva-static-page h1.fs-1d3 {
    font-size: 1.55rem !important;
    margin-bottom: 14px !important;
  }
  html.hva-page-clear-layout body.hva-static-page .post-body {
    font-size: .96rem !important;
    line-height: 1.72 !important;
  }
  html.hva-page-clear-layout body.hva-static-page .post-body h2 {
    font-size: 1.16rem !important;
  }
  .hva-display-switch {
    right: 10px !important;
    bottom: 10px !important;
  }
}



/* =========================================================
   HVA Admin Layout Customizer Cleanup v2.0.2.7
   Goals:
   - Make post detail pages consistent, centered, and readable
   - Remove forum-like chrome from normal articles
   - Keep desktop max canvas 1920px, but article reading width controlled
   - Optimize mobile/tablet separately
   ========================================================= */
:root {
  --hva-post-page-width: 1120px;
  --hva-article-shell-width: 920px;
  --hva-article-reading-width: 760px;
  --hva-article-media-width: 680px;
  --hva-post-top-gap: 22px;
}

/* Keep the global 1920 desktop canvas, but make article pages intentional */
html.hva-post-clean body.hva-post-page main.max-w {
  max-width: var(--hva-post-page-width) !important;
  width: 100% !important;
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 16px !important;
  padding-right: 16px !important;
}

html.hva-post-clean body.hva-post-page header.max-w {
  margin-bottom: var(--hva-post-top-gap) !important;
}

/* Hide global category cloud on article pages. Keep categories for homepage/search pages. */
html.hva-hide-post-label-cloud body.hva-post-page #Label1,
html.hva-hide-post-label-cloud body.hva-post-page .Label,
html.hva-hide-post-label-cloud body.hva-post-page .cloud-label-widget-content,
html.hva-hide-post-label-cloud body.hva-post-page .label-cloud {
  display: none !important;
}

/* Article title/header stack */
html.hva-post-clean body.hva-post-page h1.fs-1d3 {
  max-width: var(--hva-article-shell-width) !important;
  margin: 0 auto 12px !important;
  color: var(--hva-title, var(--hva-text-strong)) !important;
  font-size: clamp(1.55rem, 1.22rem + 1.05vw, 2.25rem) !important;
  line-height: 1.2 !important;
  letter-spacing: -.026em !important;
  font-weight: 850 !important;
  text-align: left !important;
  text-wrap: balance;
}

html.hva-post-clean body.hva-post-page .breadcrumb-nav {
  max-width: var(--hva-article-shell-width) !important;
  margin: 0 auto 10px !important;
  padding: 8px 12px !important;
  border-radius: 12px !important;
  background: var(--hva-card-2, var(--hva-card-soft)) !important;
  border: 1px solid var(--hva-line, var(--border)) !important;
  color: var(--hva-meta, var(--hva-text-muted)) !important;
  font-size: .78rem !important;
}

html.hva-post-clean body.hva-post-page .breadcrumb-nav ol {
  gap: 5px !important;
}

/* Hide old forum tools from article detail pages */
html.hva-hide-post-comment-tools body.hva-post-page .flex.jcsb.mb-7,
html.hva-hide-post-comment-tools body.hva-post-page .comment-lock,
html.hva-hide-post-comment-tools body.hva-post-page [id='myList1'] {
  display: none !important;
}

html.hva-hide-post-author body.hva-post-page article.row-x > .g343.p-10.tac,
html.hva-hide-post-author body.hva-post-page article.row-x > .g343.p-10.tac.g-profile,
html.hva-hide-post-author body.hva-post-page article.row-x > aside,
html.hva-hide-post-author body.hva-post-page article.row-x > .g-profile {
  display: none !important;
}

html.hva-post-clean body.hva-post-page article.row-x {
  display: block !important;
  max-width: var(--hva-article-shell-width) !important;
  width: 100% !important;
  margin: 0 auto 18px !important;
  border: 1px solid var(--hva-line, var(--border)) !important;
  border-radius: 18px !important;
  background: var(--hva-card, var(--hva-card-bg)) !important;
  box-shadow: 0 12px 34px rgba(0,0,0,.16) !important;
  overflow: hidden !important;
}

html.hva-theme-light.hva-post-clean body.hva-post-page article.row-x {
  box-shadow: 0 14px 42px rgba(15,23,42,.075) !important;
}

html.hva-post-clean body.hva-post-page article.row-x > .grid.gtr {
  display: block !important;
  padding: clamp(20px, 2.1vw, 34px) !important;
  background: transparent !important;
}

html.hva-hide-post-meta body.hva-post-page article.row-x > .grid.gtr > header.flex.jcsb,
html.hva-hide-post-meta body.hva-post-page article.row-x footer.jsr,
html.hva-hide-post-meta body.hva-post-page .post-header,
html.hva-hide-post-meta body.hva-post-page .post-meta,
html.hva-hide-post-meta body.hva-post-page .post-meta-line,
html.hva-hide-post-meta body.hva-post-page .feed-links,
html.hva-hide-post-meta body.hva-post-page .blog-feeds {
  display: none !important;
}

/* Unified content rhythm */
html.hva-post-clean body.hva-post-page .post-body {
  max-width: none !important;
  margin: 0 !important;
  padding: 0 !important;
  color: var(--hva-body, var(--hva-text-body)) !important;
  font-size: 1.035rem !important;
  line-height: 1.82 !important;
  letter-spacing: .001em;
}

html.hva-post-clean body.hva-post-page .post-body > * {
  margin-top: 0;
}

html.hva-unified-content body.hva-post-page .post-body :where(p, ul, ol, blockquote, table, pre, .notice-card, .cta-box),
html.hva-unified-content body.hva-post-page .post-body > :where(div, section):not(.toc-box):not(.separator):not(.cta-box):not(.notice-card),
html.hva-unified-content body.hva-post-page .post-body :where(h2, h3, h4) {
  max-width: var(--hva-article-reading-width) !important;
  margin-left: auto !important;
  margin-right: auto !important;
}

html.hva-unified-content body.hva-post-page .post-body :where(p, li) {
  color: var(--hva-body, var(--hva-text-body)) !important;
}

html.hva-unified-content body.hva-post-page .post-body p {
  margin-bottom: 1.05rem !important;
}

html.hva-unified-content body.hva-post-page .post-body ul,
html.hva-unified-content body.hva-post-page .post-body ol {
  padding-left: 1.35rem !important;
  margin-top: .65rem !important;
  margin-bottom: 1.15rem !important;
}

html.hva-unified-content body.hva-post-page .post-body li + li {
  margin-top: .34rem !important;
}

/* Media is consistently centered and not stretched across unrelated widths */
html.hva-unified-content body.hva-post-page .post-body .separator,
html.hva-unified-content body.hva-post-page .post-body > figure,
html.hva-unified-content body.hva-post-page .post-body > .tr-caption-container {
  max-width: var(--hva-article-media-width) !important;
  margin: 22px auto !important;
  text-align: center !important;
}

html.hva-unified-content body.hva-post-page .post-body img {
  display: block !important;
  max-width: min(100%, var(--hva-article-media-width)) !important;
  width: auto !important;
  height: auto !important;
  margin-left: auto !important;
  margin-right: auto !important;
  border-radius: 14px !important;
}

html.hva-theme-dark.hva-unified-content body.hva-post-page .post-body img {
  background: #f8fafc !important;
}

/* Question/answer and explanation blocks from old imported posts */
html.hva-unified-content body.hva-post-page .post-body :where(blockquote, .notice-card, .cta-box, pre) {
  padding: 16px 18px !important;
  border-radius: 14px !important;
  border: 1px solid var(--hva-line, var(--border)) !important;
  background: var(--hva-card-2, var(--hva-card-soft)) !important;
}

html.hva-unified-content body.hva-post-page .post-body blockquote {
  border-left: 4px solid var(--lime) !important;
}

html.hva-theme-light.hva-unified-content body.hva-post-page .post-body :where(blockquote, .notice-card, pre) {
  background: #f7f9fd !important;
}

/* CTA card made same width as article content */
html.hva-unified-content body.hva-post-page .post-body .cta-box {
  margin-top: 26px !important;
  background: linear-gradient(135deg, rgba(88,101,232,.12), rgba(20,184,166,.10)) !important;
  border-left: 4px solid var(--lime) !important;
}

html.hva-unified-content body.hva-post-page .post-body .cta-box .button {
  display: inline-flex !important;
  align-items: center !important;
  min-height: 36px !important;
  padding: 0 14px !important;
  border-radius: 10px !important;
}

/* TOC follows the same article grid */
html.hva-post-clean body.hva-post-page .toc-box {
  max-width: var(--hva-article-reading-width) !important;
  margin: 0 auto 22px !important;
  border-radius: 14px !important;
  background: var(--hva-card-2, var(--hva-card-soft)) !important;
  border-color: var(--hva-line, var(--border)) !important;
}

html.hva-post-clean body.hva-post-page .toc-title {
  color: var(--hva-title, var(--hva-text-strong)) !important;
}

/* Heading style: clear but not oversized */
html.hva-unified-content.hva-improved-headings body.hva-post-page .post-body h2 {
  margin-top: 2rem !important;
  margin-bottom: .7rem !important;
  padding-top: 1rem !important;
  border-top: 1px solid var(--hva-line, var(--border)) !important;
  font-size: clamp(1.22rem, 1.05rem + .45vw, 1.48rem) !important;
  line-height: 1.32 !important;
  letter-spacing: -.015em !important;
}

html.hva-unified-content.hva-improved-headings body.hva-post-page .post-body h2:first-child,
html.hva-unified-content.hva-improved-headings body.hva-post-page .post-body .toc-box + h2 {
  margin-top: 1rem !important;
}

html.hva-unified-content.hva-improved-headings body.hva-post-page .post-body h3 {
  margin-top: 1.45rem !important;
  margin-bottom: .55rem !important;
  padding-left: 12px !important;
  border-left: 3px solid var(--lime) !important;
  font-size: 1.08rem !important;
}

html.hva-unified-content body.hva-post-page .post-body strong,
html.hva-unified-content body.hva-post-page .post-body b {
  color: var(--hva-title, var(--hva-text-strong)) !important;
  font-weight: 800 !important;
}

/* Optional compact article mode */
html.hva-post-density-compact body.hva-post-page article.row-x > .grid.gtr {
  padding: 22px !important;
}

html.hva-post-density-compact body.hva-post-page .post-body {
  font-size: .99rem !important;
  line-height: 1.72 !important;
}

/* Footer/bottom links align with article shell */
html.hva-post-clean body.hva-post-page #PageList2,
html.hva-post-clean body.hva-post-page footer.max-w > .g262,
html.hva-post-clean body.hva-post-page footer.max-w > * {
  max-width: var(--hva-article-shell-width) !important;
  margin-left: auto !important;
  margin-right: auto !important;
}

/* Tablet */
@media (max-width: 1100px) {
  :root {
    --hva-post-page-width: 100%;
    --hva-article-shell-width: 900px;
    --hva-article-reading-width: 740px;
    --hva-article-media-width: 680px;
  }

  html.hva-post-clean body.hva-post-page main.max-w {
    padding-left: 14px !important;
    padding-right: 14px !important;
  }
}

@media (max-width: 760px) {
  :root {
    --hva-article-shell-width: 100%;
    --hva-article-reading-width: 100%;
    --hva-article-media-width: 100%;
    --hva-post-top-gap: 14px;
  }

  html.hva-post-clean body.hva-post-page main.max-w {
    padding-left: 10px !important;
    padding-right: 10px !important;
  }

  html.hva-post-clean body.hva-post-page h1.fs-1d3 {
    font-size: 1.32rem !important;
    line-height: 1.26 !important;
    margin-bottom: 10px !important;
  }

  html.hva-post-clean body.hva-post-page .breadcrumb-nav {
    font-size: .72rem !important;
    padding: 7px 9px !important;
  }

  html.hva-post-clean body.hva-post-page article.row-x {
    border-radius: 14px !important;
  }

  html.hva-post-clean body.hva-post-page article.row-x > .grid.gtr {
    padding: 16px 13px 18px !important;
  }

  html.hva-post-clean body.hva-post-page .post-body {
    font-size: .98rem !important;
    line-height: 1.74 !important;
  }

  html.hva-unified-content body.hva-post-page .post-body .separator,
  html.hva-unified-content body.hva-post-page .post-body > figure,
  html.hva-unified-content body.hva-post-page .post-body > .tr-caption-container {
    margin: 16px auto !important;
  }

  html.hva-post-clean body.hva-post-page .toc-box {
    margin-bottom: 18px !important;
  }
}



/* =========================================================
   HVA Admin Layout Customizer Cleanup v2.0.2.7
   - Dark-only interface
   - Restore author/avatar rail for article and comments
   - Keep fixed 1920 desktop canvas with responsive tablet/mobile
   - Add related posts at the end of article content
   ========================================================= */
:root {
  --hva-article-author-width: 112px;
  --hva-dark-page: #101418;
  --hva-dark-surface: #171c22;
  --hva-dark-surface-2: #1d242c;
  --hva-dark-border: #2a3440;
  --hva-dark-border-soft: #22303b;
  --hva-dark-title: #f3f7fb;
  --hva-dark-body: #d7e0ea;
  --hva-dark-muted: #95a3b5;
}

html.hva-dark-only,
html.hva-dark-only body {
  background: var(--hva-dark-page) !important;
  color: var(--hva-dark-body) !important;
}

html.hva-dark-only .hva-display-switch,
html.hva-no-display-switch .hva-display-switch {
  display: none !important;
}

html.hva-dark-only body,
html.hva-dark-only .g161 {
  background-color: var(--hva-dark-page) !important;
}

html.hva-dark-only .g262,
html.hva-dark-only .latest-list-wrap,
html.hva-dark-only .home-category-block,
html.hva-dark-only .featured-card,
html.hva-dark-only .latest-card {
  background-color: var(--hva-dark-surface) !important;
}

html.hva-dark-only .g343,
html.hva-dark-only .breadcrumb-nav,
html.hva-dark-only .toc-box,
html.hva-dark-only .post-body blockquote,
html.hva-dark-only .post-body pre,
html.hva-dark-only .post-body table,
html.hva-dark-only .post-card-badge,
html.hva-dark-only .label-size a {
  background-color: var(--hva-dark-surface-2) !important;
  border-color: var(--hva-dark-border) !important;
}

/* Article shell with restored author rail */
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page main.max-w {
  max-width: var(--hva-post-page-width) !important;
  padding-left: 16px !important;
  padding-right: 16px !important;
}

html.hva-post-clean.hva-show-post-author-rail body.hva-post-page h1.fs-1d3,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .breadcrumb-nav,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .flex.jcsb.mb-7,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page article.row-x,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page #comments,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .post-feeds,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .blog-feeds {
  max-width: var(--hva-article-shell-width) !important;
  width: 100% !important;
  margin-left: auto !important;
  margin-right: auto !important;
}

html.hva-post-clean.hva-show-post-author-rail body.hva-post-page h1.fs-1d3 {
  margin-bottom: 12px !important;
  color: var(--hva-dark-title) !important;
  font-weight: 850 !important;
}

html.hva-post-clean.hva-show-post-author-rail body.hva-post-page article.row-x {
  display: grid !important;
  grid-template-columns: var(--hva-article-author-width) minmax(0, 1fr) !important;
  border: 1px solid var(--hva-dark-border) !important;
  border-radius: 18px !important;
  background: var(--hva-dark-surface) !important;
  box-shadow: 0 14px 40px rgba(0,0,0,.22) !important;
  overflow: hidden !important;
}

html.hva-post-clean.hva-show-post-author-rail body.hva-post-page article.row-x > .g343.p-10.tac,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page article.row-x > .g343.p-10.tac.g-profile {
  display: block !important;
  min-width: 0 !important;
  padding: 16px 10px !important;
  background: #202832 !important;
  border-right: 1px solid var(--hva-dark-border) !important;
  color: var(--hva-dark-muted) !important;
  text-align: center !important;
}

html.hva-post-clean.hva-show-post-author-rail body.hva-post-page article.row-x > .grid.gtr {
  display: grid !important;
  grid-template-rows: auto 1fr auto !important;
  min-width: 0 !important;
  padding: 18px 22px 22px !important;
  background: transparent !important;
}

html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .g-profile img,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .h-73,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .w-73 {
  width: 62px !important;
  height: 62px !important;
  border-radius: 14px !important;
}

html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .auth,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .auth a,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .badge a,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .g-profile a {
  color: var(--hva-dark-title) !important;
  font-size: .82rem !important;
  font-weight: 800 !important;
}

html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .post-header,
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page article.row-x > .grid.gtr > header.flex.jcsb {
  margin: 0 0 14px !important;
  padding-bottom: 12px !important;
  border-bottom: 1px solid var(--hva-dark-border-soft) !important;
  color: var(--hva-dark-muted) !important;
  font-size: .82rem !important;
}

html.hva-post-clean.hva-show-post-comment-tools body.hva-post-page .flex.jcsb.mb-7 {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 12px !important;
  margin-top: 0 !important;
  margin-bottom: 12px !important;
}

html.hva-post-clean.hva-show-post-comment-tools body.hva-post-page .flex.jcsb.mb-7 button,
html.hva-post-clean.hva-show-post-comment-tools body.hva-post-page .comments .flex.jcsb button {
  min-height: 32px !important;
  padding: 5px 10px !important;
  border-radius: 10px !important;
  border: 1px solid var(--hva-dark-border) !important;
  background: var(--hva-dark-surface-2) !important;
  color: var(--hva-dark-muted) !important;
  font-size: .78rem !important;
}

/* Keep post body, TOC, CTA and related posts on one consistent reading axis */
html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .post-body {
  color: var(--hva-dark-body) !important;
  font-size: 1.015rem !important;
  line-height: 1.82 !important;
}

html.hva-unified-content body.hva-post-page .post-body :where(p, ul, ol, blockquote, table, pre, .notice-card, .cta-box, .related-posts),
html.hva-unified-content body.hva-post-page .post-body > :where(div, section):not(.toc-box):not(.separator):not(.cta-box):not(.notice-card):not(.related-posts),
html.hva-unified-content body.hva-post-page .post-body :where(h2, h3, h4),
html.hva-post-clean body.hva-post-page .toc-box {
  max-width: var(--hva-article-reading-width) !important;
  margin-left: auto !important;
  margin-right: auto !important;
}

html.hva-unified-content body.hva-post-page .post-body .separator,
html.hva-unified-content body.hva-post-page .post-body > figure,
html.hva-unified-content body.hva-post-page .post-body > .tr-caption-container {
  max-width: var(--hva-article-media-width) !important;
}

html.hva-dark-only body.hva-post-page .post-body :where(p, li) {
  color: var(--hva-dark-body) !important;
}

html.hva-dark-only body.hva-post-page .post-body :where(h2, h3, h4, strong, b) {
  color: var(--hva-dark-title) !important;
}

/* Related posts */
html.hva-hide-related-posts body.hva-post-page .related-posts {
  display: none !important;
}

body.hva-post-page .related-posts {
  margin-top: 30px !important;
  padding-top: 22px !important;
  border-top: 1px solid var(--hva-dark-border-soft) !important;
}

body.hva-post-page .related-posts .title,
body.hva-post-page .related-posts .heading,
body.hva-post-page .related-title {
  margin: 0 0 14px !important;
  color: var(--hva-dark-title) !important;
  font-size: 1.06rem !important;
  line-height: 1.35 !important;
  font-weight: 850 !important;
}

body.hva-post-page .related.style-2 {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 12px !important;
  padding: 0 !important;
  margin: 0 !important;
  list-style: none !important;
}

body.hva-post-page .related .item-related {
  height: 100% !important;
  border: 1px solid var(--hva-dark-border) !important;
  border-radius: 14px !important;
  background: var(--hva-dark-surface-2) !important;
  overflow: hidden !important;
  transition: transform .18s ease, border-color .18s ease, background .18s ease !important;
}

body.hva-post-page .related .item-related:hover {
  transform: translateY(-2px) !important;
  border-color: var(--lime) !important;
  background: #222b36 !important;
}

body.hva-post-page .related .item-thumbnail img {
  width: 100% !important;
  aspect-ratio: 16/9 !important;
  object-fit: cover !important;
  border-radius: 0 !important;
  background: #f8fafc !important;
}

body.hva-post-page .related .item-title {
  padding: 10px 11px 12px !important;
  color: var(--hva-dark-title) !important;
  font-size: .86rem !important;
  line-height: 1.42 !important;
  font-weight: 750 !important;
}

body.hva-post-page .related .item-title a {
  color: inherit !important;
  text-decoration: none !important;
}

/* Comments remain aligned with article cards */
body.hva-post-page #comments,
body.hva-post-page .comments.threaded {
  margin-top: 18px !important;
  color: var(--hva-dark-body) !important;
}

body.hva-post-page .comments .title {
  color: var(--hva-dark-title) !important;
  font-size: 1.05rem !important;
  margin: 0 0 12px !important;
}

/* Mobile/tablet: author rail becomes a compact top bar */
@media (max-width: 900px) {
  html.hva-post-clean.hva-show-post-author-rail body.hva-post-page article.row-x {
    grid-template-columns: 1fr !important;
    border-radius: 15px !important;
  }

  html.hva-post-clean.hva-show-post-author-rail body.hva-post-page article.row-x > .g343.p-10.tac,
  html.hva-post-clean.hva-show-post-author-rail body.hva-post-page article.row-x > .g343.p-10.tac.g-profile {
    display: flex !important;
    align-items: center !important;
    gap: 10px !important;
    text-align: left !important;
    border-right: 0 !important;
    border-bottom: 1px solid var(--hva-dark-border) !important;
    padding: 10px 12px !important;
  }

  html.hva-post-clean.hva-show-post-author-rail body.hva-post-page article.row-x > .grid.gtr {
    padding: 15px 13px 18px !important;
  }

  html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .g-profile img,
  html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .h-73,
  html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .w-73 {
    width: 50px !important;
    height: 50px !important;
    margin-bottom: 0 !important;
  }

  body.hva-post-page .related.style-2 {
    grid-template-columns: 1fr !important;
  }
}

@media (max-width: 640px) {
  html.hva-post-clean.hva-show-post-author-rail body.hva-post-page main.max-w {
    padding-left: 10px !important;
    padding-right: 10px !important;
  }

  html.hva-post-clean.hva-show-post-author-rail body.hva-post-page h1.fs-1d3 {
    font-size: 1.35rem !important;
  }

  html.hva-post-clean.hva-show-post-author-rail body.hva-post-page .post-body {
    font-size: .98rem !important;
    line-height: 1.74 !important;
  }
}


/* =========================================================
   HVA Admin Layout Customizer Cleanup v2.0.2.7
   - Minimal runtime options
   - Conditional author profile links
   - Cleaner readable quote / legacy content panels
   ========================================================= */
.hva-author-photo-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  text-decoration: none !important;
}

.hva-author-photo-link img {
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}

.hva-author-photo-link:hover img {
  transform: translateY(-1px);
  box-shadow: 0 8px 18px rgba(0,0,0,.24);
}

.hva-author-name-plain {
  display: inline-block;
  color: var(--white);
  font-weight: 700;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote,
html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel {
  max-width: var(--hva-article-reading-width) !important;
  margin: 20px auto !important;
  padding: 18px 20px 18px 22px !important;
  border: 1px solid #313b4b !important;
  border-left: 4px solid var(--lime) !important;
  border-radius: 16px !important;
  background: linear-gradient(180deg, rgba(255,255,255,.045), rgba(255,255,255,.025)) !important;
  color: #dbe4f0 !important;
  line-height: 1.78 !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.04), 0 10px 28px rgba(0,0,0,.14) !important;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote::before,
html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel::before {
  content: "Ghi chú";
  display: inline-flex;
  align-items: center;
  width: fit-content;
  margin: 0 0 10px;
  padding: 2px 8px;
  border: 1px solid rgba(108,108,254,.45);
  border-radius: 999px;
  background: rgba(108,108,254,.13);
  color: #cfd4ff;
  font-size: .72rem;
  font-weight: 800;
  letter-spacing: .02em;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel :where(div, p, span, li, td, th, section),
html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote :where(div, p, span, li, td, th, section) {
  background: transparent !important;
  color: #dbe4f0 !important;
  border-color: rgba(148,163,184,.22) !important;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel :where(strong, b),
html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote :where(strong, b) {
  color: #ffffff !important;
  font-weight: 800 !important;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel a,
html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote a {
  color: #aab4ff !important;
  font-weight: 700;
  text-decoration-thickness: .08em;
  text-underline-offset: 3px;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel :where(ul, ol),
html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote :where(ul, ol) {
  margin: .65rem 0 .8rem !important;
  padding-left: 1.3rem !important;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel > :last-child,
html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote > :last-child {
  margin-bottom: 0 !important;
}

@media (max-width: 760px) {
  html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote,
  html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel {
    padding: 15px 15px 15px 17px !important;
    border-radius: 13px !important;
  }
}


/* =========================================================
   HVA Admin Layout + Customizer Cleanup v2.0.2.7
   - Blogger Layout: widget titles numbered by admin area
   - Blogger Customizer: main colors / widths mapped to CSS variables
   - Quote / legacy panels: cleaner, readable, less cluttered
   ========================================================= */
:root {
  --lime: $(hva.accent.color);
  --dark: $(hva.body.bg.color);
  --mediumdark: $(hva.surface.color);
  --dark34: $(hva.section.bg.color);
  --surface: $(hva.surface.color);
  --surface2: $(hva.panel.color);
  --border: $(hva.border.color);
  --muted: $(hva.muted.color);
  --light: $(hva.text.color);
  --mediumlight: $(hva.secondary.text.color);
  --white: $(hva.heading.color);
  --radius: $(hva.radius);
  --hva-fixed-width: $(hva.site.width);
  --hva-site-width: $(hva.site.width);
  --hva-article-shell-width: $(hva.article.shell.width);
  --hva-article-reading-width: $(hva.article.reading.width);
  --hva-article-media-width: $(hva.article.media.width);
  --hva-article-author-width: $(hva.author.rail.width);
}

html.hva-dark-only .header-widget {
  background: linear-gradient(135deg, $(hva.header.start.color), $(hva.header.end.color)) !important;
}

html.hva-soft-notice-bar .notice-card,
html.hva-soft-notice-bar .g4d0 .notice-card,
html.hva-soft-notice-bar .g4d0 {
  background: $(hva.notice.bg.color) !important;
  border-color: $(hva.notice.border.color) !important;
  color: var(--light) !important;
}

/* Remove the extra 'Ghi chú' label from old quote panels; make the quote itself easier to scan. */
html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote::before,
html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel::before {
  content: none !important;
  display: none !important;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote,
html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel {
  max-width: var(--hva-article-reading-width) !important;
  margin: 22px auto !important;
  padding: 18px 20px !important;
  border: 1px solid var(--border) !important;
  border-left: 4px solid var(--lime) !important;
  border-radius: 14px !important;
  background: var(--surface2) !important;
  color: var(--light) !important;
  font-size: .96rem !important;
  line-height: 1.78 !important;
  box-shadow: none !important;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel :where(div, p, span, li, td, th, section),
html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote :where(div, p, span, li, td, th, section) {
  background: transparent !important;
  color: var(--light) !important;
  border-color: rgba(148,163,184,.22) !important;
  box-shadow: none !important;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel :where(p, ul, ol),
html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote :where(p, ul, ol) {
  margin-top: .55rem !important;
  margin-bottom: .55rem !important;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel :where(strong, b),
html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote :where(strong, b) {
  color: var(--white) !important;
  font-weight: 800 !important;
}

html.hva-clean-quote-blocks body.hva-post-page .post-body .hva-readable-panel a,
html.hva-clean-quote-blocks body.hva-post-page .post-body blockquote a {
  color: var(--lime) !important;
  font-weight: 750 !important;
  text-underline-offset: 3px;
}

html.hva-admin-cleaned .theme-version {
  display: none !important;
}



/* =========================================================
   HVA Responsive Article + Comments + Background Ads v2.0.2.8
   - Article content scales with the main layout and avoids uneven large/small blocks
   - Related posts are intended to render below the comment area
   - Main post author panel is visually stronger than commenter panels
   - Left/right background ad HTML widgets with placeholders
   ========================================================= */
:root {
  --hva-bg-ad-width: $(hva.bg.ad.width);
  --hva-bg-ad-top: $(hva.bg.ad.top);
  --hva-post-gap: clamp(12px, 1.4vw, 22px);
}

html.hva-responsive-article-flow body.hva-post-page main.max-w,
html.hva-responsive-article-flow body.hva-post-page h1.fs-1d3,
html.hva-responsive-article-flow body.hva-post-page .breadcrumb-nav,
html.hva-responsive-article-flow body.hva-post-page .flex.jcsb.mb-7,
html.hva-responsive-article-flow body.hva-post-page article.row-x,
html.hva-responsive-article-flow body.hva-post-page #comments,
html.hva-responsive-article-flow body.hva-post-page .related-posts.hva-related-after-comments,
html.hva-responsive-article-flow body.hva-post-page .post-feeds,
html.hva-responsive-article-flow body.hva-post-page .blog-feeds {
  width: min(100%, var(--hva-article-shell-width)) !important;
  max-width: var(--hva-article-shell-width) !important;
}

html.hva-responsive-article-flow body.hva-post-page main.max-w {
  width: min(calc(100% - 32px), var(--hva-post-page-width)) !important;
  max-width: var(--hva-post-page-width) !important;
}

html.hva-responsive-article-flow body.hva-post-page article.row-x {
  margin-bottom: var(--hva-post-gap) !important;
}

html.hva-responsive-article-flow body.hva-post-page .post-body {
  font-size: clamp(.98rem, .93rem + .18vw, 1.035rem) !important;
}

html.hva-responsive-article-flow body.hva-post-page .post-body :where(p, ul, ol, blockquote, table, pre, .notice-card, .cta-box),
html.hva-responsive-article-flow body.hva-post-page .post-body > :where(div, section):not(.toc-box):not(.separator):not(.cta-box):not(.notice-card):not(.related-posts),
html.hva-responsive-article-flow body.hva-post-page .post-body :where(h2, h3, h4),
html.hva-responsive-article-flow body.hva-post-page .toc-box {
  width: min(100%, var(--hva-article-reading-width)) !important;
  max-width: var(--hva-article-reading-width) !important;
}

html.hva-responsive-article-flow body.hva-post-page .post-body .separator,
html.hva-responsive-article-flow body.hva-post-page .post-body > figure,
html.hva-responsive-article-flow body.hva-post-page .post-body > .tr-caption-container,
html.hva-responsive-article-flow body.hva-post-page .post-body .hva-media-balanced {
  width: min(100%, var(--hva-article-media-width)) !important;
  max-width: var(--hva-article-media-width) !important;
  margin-left: auto !important;
  margin-right: auto !important;
}

html.hva-responsive-article-flow body.hva-post-page .post-body .hva-media-balanced img {
  width: 100% !important;
  max-width: 100% !important;
  height: auto !important;
  object-fit: contain !important;
}

/* Main post author panel: stronger and clearer than normal comment authors */
html.hva-highlight-main-author body.hva-post-page article.hva-post-main-card > .g343.p-10.tac,
html.hva-highlight-main-author body.hva-post-page article.hva-post-main-card > .g343.p-10.tac.g-profile {
  background: linear-gradient(180deg, rgba(124,131,255,.20), rgba(32,40,50,.96)) !important;
  border-right: 1px solid rgba(124,131,255,.42) !important;
  box-shadow: inset -1px 0 0 rgba(255,255,255,.035) !important;
}

html.hva-highlight-main-author body.hva-post-page article.hva-post-main-card > .g343 .hva-author-photo-link img,
html.hva-highlight-main-author body.hva-post-page article.hva-post-main-card > .g343 img {
  border: 2px solid rgba(124,131,255,.65) !important;
  box-shadow: 0 0 0 4px rgba(124,131,255,.10), 0 10px 24px rgba(0,0,0,.28) !important;
}

html.hva-highlight-main-author body.hva-post-page article.hva-post-main-card > .g343 > .auth::before {
  content: "Tác giả";
  display: inline-flex;
  align-items: center;
  margin: 0 0 7px;
  padding: 2px 8px;
  border: 1px solid rgba(124,131,255,.50);
  border-radius: 999px;
  background: rgba(124,131,255,.16);
  color: #d8dcff;
  font-size: .68rem;
  line-height: 1.45;
  font-weight: 850;
  letter-spacing: .04em;
  text-transform: uppercase;
}

html.hva-highlight-main-author body.hva-post-page article.hva-comment-card > .g343.p-10.tac,
html.hva-highlight-main-author body.hva-post-page article.hva-comment-card > .g343.p-10.tac.g-profile {
  background: #1c232c !important;
}

/* Related posts now live below comments, not inside the article body */
body.hva-post-page .related-posts.hva-related-after-comments {
  margin: 20px auto 0 !important;
  padding: 18px !important;
  border: 1px solid var(--hva-dark-border) !important;
  border-radius: 18px !important;
  background: var(--hva-dark-surface) !important;
  box-shadow: 0 12px 34px rgba(0,0,0,.16) !important;
}

body.hva-post-page .related-posts.hva-related-after-comments .title,
body.hva-post-page .related-posts.hva-related-after-comments .heading,
body.hva-post-page .related-posts.hva-related-after-comments .related-title {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--hva-dark-border-soft);
}

body.hva-post-page .related-posts.hva-related-after-comments .title::before,
body.hva-post-page .related-posts.hva-related-after-comments .heading::before,
body.hva-post-page .related-posts.hva-related-after-comments .related-title::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--lime);
  box-shadow: 0 0 0 4px rgba(124,131,255,.12);
}

/* Background ad widgets */
.hva-background-ads {
  pointer-events: none;
}

.hva-bg-ad {
  position: fixed !important;
  top: var(--hva-bg-ad-top) !important;
  width: var(--hva-bg-ad-width) !important;
  min-height: 520px;
  z-index: 15;
  pointer-events: auto;
}

.hva-bg-ad-left {
  left: max(14px, calc((100vw - var(--hva-site-width)) / 2 + 14px)) !important;
}

.hva-bg-ad-right {
  right: max(14px, calc((100vw - var(--hva-site-width)) / 2 + 14px)) !important;
}

.hva-bg-ad .widget-content,
.hva-bg-ad-placeholder {
  min-height: 520px;
  border: 1px dashed rgba(124,131,255,.40);
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(124,131,255,.10), rgba(255,255,255,.025));
  color: var(--muted);
  font-size: .78rem;
  line-height: 1.45;
  display: grid;
  place-items: center;
  text-align: center;
  padding: 14px;
}

.hva-bg-ad-placeholder strong {
  display: block;
  margin-bottom: 6px;
  color: var(--white);
  font-size: .88rem;
}

html.hva-hide-background-ads .hva-bg-ad,
html:not(.hva-show-background-ads) .hva-bg-ad {
  display: none !important;
}

@media (max-width: 1440px) {
  .hva-bg-ad { display: none !important; }
}

@media (max-width: 900px) {
  html.hva-responsive-article-flow body.hva-post-page main.max-w {
    width: min(calc(100% - 22px), var(--hva-post-page-width)) !important;
  }
  html.hva-highlight-main-author body.hva-post-page article.hva-post-main-card > .g343.p-10.tac,
  html.hva-highlight-main-author body.hva-post-page article.hva-post-main-card > .g343.p-10.tac.g-profile {
    border-right: 0 !important;
    border-bottom: 1px solid rgba(124,131,255,.35) !important;
  }
  body.hva-post-page .related-posts.hva-related-after-comments {
    padding: 14px !important;
    border-radius: 15px !important;
  }
}

@media (max-width: 640px) {
  html.hva-responsive-article-flow body.hva-post-page main.max-w {
    width: min(calc(100% - 16px), var(--hva-post-page-width)) !important;
  }
  body.hva-post-page .related-posts.hva-related-after-comments .related.style-2 {
    grid-template-columns: 1fr !important;
  }
}

