    if(!value){return '';}
    var raw=value;
    try{raw=new URL(value, location.origin).pathname;}catch(error){}
    var marker='/search/label/';
    var index=raw.indexOf(marker);
    var label=index>=0?raw.substring(index+marker.length):raw;
    label=label.split('?')[0].split('#')[0].replace(/^\/+|\/+$/g,'');
    try{return decodeURIComponent(label.replace(/\+/g,' '));}catch(error){return label;}
  }
  function loadBlock(block,index){
    var grid=block.querySelector('.home-category-grid');
    var loading=block.querySelector('.home-category-loading');
    var label=labelFrom(block.getAttribute('data-category-url'));
    if(!grid||!label){if(loading){loading.textContent='Chưa cấu hình đúng label.';}return;}
    var callback='homeCategoryPosts_'+Date.now()+'_'+index;
    window[callback]=function(data){
      try{
        var entries=data&&data.feed&&data.feed.entry?data.feed.entry:[];
        if(loading){loading.style.display='none';}
        if(!entries.length){grid.innerHTML='<div class="home-category-empty">Chưa có bài viết trong danh mục này.</div>';return;}
        entries.slice(0,4).forEach(function(entry){
          var card=document.createElement('article');
          card.className='home-category-card';
          var image=document.createElement('img');
          image.className='home-category-thumb';
          image.loading='lazy';
          image.alt=textOf(entry.title)||label;
          image.src=thumbOf(entry);
          var content=document.createElement('div');
          content.style.minWidth='0';
          var title=document.createElement('a');
          title.className='home-category-card-title';
          title.href=postLink(entry);
          title.textContent=textOf(entry.title)||'Bài viết';
          var snippet=document.createElement('div');
          snippet.className='home-category-card-snippet';
          snippet.textContent=textOf(entry.summary||entry.content).substring(0,120);
          content.appendChild(title);
          content.appendChild(snippet);
          card.appendChild(image);
          card.appendChild(content);
          grid.appendChild(card);
        });
      }finally{delete window[callback];}
    };
    var script=document.createElement('script');
    script.src=location.origin.replace(/\/$/,'')+'/feeds/posts/summary/-/'+encodeURIComponent(label)+'?alt=json-in-script&max-results=4&callback='+callback;
    script.onerror=function(){if(loading){loading.textContent='Không tải được danh mục: '+label;}delete window[callback];};
    document.head.appendChild(script);
  }
  document.querySelectorAll('.home-category-block').forEach(loadBlock);
})();
