body.script:
//
document.addEventListener('DOMContentLoaded',function(){
  document.querySelectorAll('.download').forEach(function(button){
    button.addEventListener('click',function(event){
      event.preventDefault();
      var postId=button.getAttribute('name')||button.dataset.postId;
      if(!postId){return;}
      localStorage.setItem('luu_id',postId);
      var callbackName='downloadFeedCallback_'+Date.now();
      window[callbackName]=function(feed){
        try{
          var links=(feed&&feed.entry&&feed.entry.link)||[];
          links.forEach(function(link){
            if(link.rel==='enclosure'&&link.type==='text/html'&&link.href){localStorage.setItem('luu_get_link',link.href);}
          });
        } finally {
          delete window[callbackName];
          location.href='/p/download.html';
        }
      };
      var script=document.createElement('script');
      script.src='/feeds/posts/summary/'+encodeURIComponent(postId)+'?alt=json-in-script&callback='+callbackName;
      script.onerror=function(){delete window[callbackName];};
      document.head.appendChild(script);
    });
  });
  var id=localStorage.getItem('luu_id');
  var getLink=localStorage.getItem('luu_get_link');
  var wrapper=document.querySelector('.time-wrapper');
  var countdown=document.getElementById('timer-countdown');
  var target=document.querySelector('.getlink-button');
  if(id&&getLink&&wrapper&&countdown&&target){
    wrapper.classList.remove('hidden');
    var timer=15;
    var downloadTimer=setInterval(function(){
      countdown.textContent=timer;
      timer-=1;
      if(timer<0){
        clearInterval(downloadTimer);
        countdown.textContent='0';
        var link=document.createElement('a');
        link.href=getLink;
        link.target='_blank';
        link.rel='noopener nofollow';
        link.title='Get link';
        link.textContent='Get link';
        target.textContent='';
        target.appendChild(link);
      }
    },1000);
  }
});
