b:if.script:
//
document.addEventListener('DOMContentLoaded',function(){
  var opt=window.HVA_UI_OPTIONS||{};
  var body=document.querySelector('.post-body');
  var toc=document.getElementById('post-toc');
  var list=document.getElementById('post-toc-list');
  if(!body){return;}

  var postTitle=(document.querySelector('body.hva-post-page h1')||{}).textContent||document.title||'Học Viện Ads';
  postTitle=postTitle.trim();

  if(opt.improveImageAlt!==false){
    [].slice.call(body.querySelectorAll('img')).forEach(function(img,index){
      if(!img.getAttribute('alt')){
        img.setAttribute('alt',postTitle+(index?(' - hình minh họa '+(index+1)):' - hình minh họa'));
      }
      if(!img.getAttribute('loading')){img.setAttribute('loading','lazy');}
      if(!img.getAttribute('decoding')){img.setAttribute('decoding','async');}
    });
  }

  if(opt.showReadingProgress!==false && !document.querySelector('.hva-reading-progress')){
    var progress=document.createElement('div');
    progress.className='hva-reading-progress';
    progress.setAttribute('aria-hidden','true');
    progress.innerHTML='<span></span>';
    document.body.appendChild(progress);
    var bar=progress.querySelector('span');
    var updateProgress=function(){
      var article=body;
      var top=article.getBoundingClientRect().top+window.pageYOffset;
      var height=Math.max(article.scrollHeight-window.innerHeight,1);
      var pct=Math.min(1,Math.max(0,(window.pageYOffset-top)/height));
      bar.style.width=(pct*100).toFixed(2)+'%';
    };
    updateProgress();
    window.addEventListener('scroll',updateProgress,{passive:true});
    window.addEventListener('resize',updateProgress);
  }

  if(!toc||!list||opt.enhancedPostToc===false){return;}
  var maxDepth=parseInt(opt.postTocMaxDepth,10)||3;
  var selector=maxDepth>=4?'h2,h3,h4':(maxDepth>=3?'h2,h3':'h2');
  var headings=[].slice.call(body.querySelectorAll(selector)).filter(function(item){
    var text=item.textContent.replace('#','').trim();
    return text.length>0 && !item.closest('.toc-box,.cta-box,.notice-card,.related-posts');
  });
  var minHeadings=parseInt(opt.postTocMinHeadings,10)||2;
  if(headings.length<minHeadings){return;}

  var used={};
  function slugify(text){
    return text.toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
      .replace(/đ/g,'d')
      .replace(/[^a-z0-9\s-]/g,'')
      .trim()
      .replace(/\s+/g,'-')
      .replace(/-+/g,'-') || 'section';
  }

  list.innerHTML='';
  headings.forEach(function(heading,index){
    var cleanText=heading.textContent.replace('#','').trim();
    var base=heading.id||slugify(cleanText);
    var id=base;
    if(used[id]){id=base+'-'+(index+1);}
    used[id]=true;
    heading.id=id;

    if(opt.autoHeadingAnchors!==false && !heading.querySelector('.hva-heading-anchor')){
      var anchor=document.createElement('a');
      anchor.className='hva-heading-anchor';
      anchor.href='#'+id;
      anchor.setAttribute('aria-label','Link tới mục: '+cleanText);
      anchor.textContent='#';
      heading.appendChild(anchor);
    }

    var li=document.createElement('li');
    var tag=heading.tagName.toLowerCase();
    li.className=tag==='h4'?'toc-h3':(tag==='h3'?'toc-h3':'toc-h2');
    li.dataset.target=id;
    var link=document.createElement('a');
    link.href='#'+id;
    link.textContent=cleanText;
    li.appendChild(link);
    list.appendChild(li);
  });

  var toggle=toc.querySelector('.toc-toggle');
  function setCollapsed(collapsed){
    toc.classList.toggle('is-collapsed',collapsed);
    if(toggle){
      toggle.textContent=collapsed?'Mở mục lục':'Thu gọn';
      toggle.setAttribute('aria-expanded',collapsed?'false':'true');
    }
  }
  if(toggle){
    toggle.addEventListener('click',function(){setCollapsed(!toc.classList.contains('is-collapsed'));});
  }
  setCollapsed(!!opt.postTocMobileCollapsed && window.innerWidth<760);

  if(opt.highlightActiveHeading!==false && 'IntersectionObserver' in window){
    var tocItems=[].slice.call(list.querySelectorAll('li'));
    var setActive=function(id){
      tocItems.forEach(function(li){li.classList.toggle('is-active',li.dataset.target===id);});
    };
    var observer=new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){setActive(entry.target.id);}
      });
    },{rootMargin:'-18% 0px -72% 0px',threshold:0.01});
    headings.forEach(function(h){observer.observe(h);});
  }

  toc.classList.add('active');
});
//
